const owned=new Set(['ironSword']),accessories=new Set(),tamed=new Set();let weapon='ironSword',armor=null,hunger=20,foodChoice='berries',harvestCooldown=0;const trust=[0,0,0];
const foods={berries:{name:'Wild Berries',fill:3,detail:'Found in Mosswood · tames hares'},nectar:{name:'Sweet Nectar',fill:2,detail:'Coastal flowers · tames moon moths'},fish:{name:'Raw Fish',fill:2,detail:'Catch near water · cook for better food'},grilled:{name:'Grilled Fish',fill:7,detail:'Cook raw fish and wood · tames drakes'},stew:{name:'Forest Stew',fill:10,detail:'Cook berries and nectar · hearty meal'}};
const forage=[];for(let x=31;x<W-10;x+=15){let zone=biomeAt(x*T);if([2,3,4,6].includes(zone))continue;const y=surface[x]*T;if(get(x,surface[x]-1)===8)continue;forage.push({x:x*T,y:y-12,kind:zone===0?'berries':'nectar',ready:0})}
const wildMounts=[{id:0,x:31*T,y:surface[31]*T-12},{id:1,x:333*T,y:surface[333]*T-12},{id:2,x:612*T,y:surface[612]*T-12}];
recipes.push({name:'Long spear',cost:{3:6,2:8},detail:'6 wood · 8 stone · ranged thrust',kind:'item',item:'ironSpear'},{name:'Crystal bow',cost:{3:10,5:5},detail:'10 wood · 5 crystal · fast arrows',kind:'item',item:'crystalBow'},{name:'Copper armor',cost:{4:12,2:6},detail:'12 copper · 6 stone · 4 defense',kind:'item',item:'copperArmor'},{name:'Swift boots',cost:{4:8,3:8},detail:'8 copper · 8 wood · speed and dash boost',kind:'item',item:'swiftBoots'},{name:'Crystal pickaxe',cost:{4:12,5:6},detail:'12 copper · 6 crystal · fastest mining',kind:'crystalpick'},{name:'Grilled fish × 2',cost:{fish:2,3:1},detail:'2 raw fish · 1 wood · restores 7 food each',kind:'cook'},{name:'Forest stew',cost:{berries:3,nectar:2},detail:'3 berries · 2 nectar · restores 10 food',kind:'stew'});
function equipItem(id){if(adminReckoning)return false;const it=items[id];if(!it||!owned.has(id)||it.adminOnly&&!adminUnlocked)return false;if(it.type==='weapon'){weapon=id;if(id!=='shadowFists')shadowFormTime=0;selected=1}else if(it.type==='armor')armor=armor===id?null:id;else accessories.has(id)?accessories.delete(id):accessories.add(id);inventory();updatePack();updateStyleHud();notify(it.name+' '+(weapon===id||armor===id||accessories.has(id)?'equipped':'removed'));return true}
function updatePack(){updatePetsMenu();updateSupplies();updateStyles();if(!$('equipment-list'))return;$('equipped-summary').textContent=`${items[weapon].name} · ${armor?items[armor].name:'No armor'} · ${[...accessories].map(i=>items[i].name).join(', ')||'No accessories'}`;$('equipment-list').innerHTML='';for(const [id,it]of Object.entries(items)){if(styleDefs[id])continue;const have=owned.has(id),active=weapon===id||armor===id||accessories.has(id),row=document.createElement('div');row.className='recipe';row.innerHTML=`<div><strong>${it.name}</strong><small>${it.detail}<br>${it.source}</small></div><button ${have?'':'disabled'}>${active?'Equipped':have?'Equip':'Not found'}</button>`;row.querySelector('button').onclick=()=>equipItem(id);$('equipment-list').appendChild(row)}$('food-list').innerHTML='';for(const [id,f]of Object.entries(foods)){const row=document.createElement('div');row.className='recipe';row.innerHTML=`<div><strong>${f.name} × ${bag[id]}</strong><small>+${f.fill} food · ${f.detail}${foodChoice===id?' · V shortcut':''}</small></div><button ${bag[id]<=0||hunger>=20?'disabled':''}>Eat</button>`;row.querySelector('button').onclick=()=>eat(id);$('food-list').appendChild(row)}}
function eat(id){if(!started||!foods[id]||bag[id]<=0||hunger>=20){notify(hunger>=20?'Your belly is full.':'No food left · H to gather, G for provisions');return false}foodChoice=id;bag[id]--;hunger=Math.min(20,hunger+foods[id].fill);updatePack();notify('Ate '+foods[id].name+' · food '+Math.ceil(hunger)+'/20');beep(360);return true}
function harvest(){if(!started)return false;if(harvestCooldown>0){notify('Give it a moment before gathering again.');return false}let node=forage.find(f=>f.ready<=time&&Math.hypot(f.x-p.x,f.y-(p.y+20))<95);if(node){bag[node.kind]+=4;node.ready=time+60;harvestCooldown=.7;updatePack();notify('Gathered 4 '+foods[node.kind].name);return true}let water=false;for(let dx=-3;dx<=3;dx++)for(let dy=-3;dy<=3;dy++)if(get(Math.floor(p.x/T)+dx,Math.floor(p.y/T)+dy)===8)water=true;if(water){bag.fish+=2;harvestCooldown=5;updatePack();notify('Caught 2 raw fish · Cook them with wood');return true}notify('Stand near berry bushes, coastal flowers or water.');return false}
function feedMount(){if(!started)return false;let w=wildMounts.find(w=>!tamed.has(w.id)&&Math.hypot(w.x-p.x,w.y-(p.y+20))<105);if(!w){notify('No wild mount nearby. Look for creatures marked T.');return false}let id=w.id,food=['berries','nectar','grilled'][id];if(id===2&&!defeated.has(2)){notify('Defeat Ashwing before taming an Ember Drake.');return false}if(bag[food]<1){notify('This mount wants '+foods[food].name+'. Gather or cook some first.');return false}bag[food]--;trust[id]++;burst(w.x,w.y,'#efa4ae',6);if(trust[id]>=3){tamed.add(id);mountChoice=id;notify(mounts[id].name+' tamed! Press R to ride.')}else notify(mounts[id].name+' trust '+trust[id]+'/3 · Feed again with T');updateAdventure();updatePack();return true}
function grantLoot(id){for(const key of [['thornBlade','barkArmor'],['tidalSpear','glider'],['emberBow','obsidianArmor'],['frostbrand','frostArmor'],['sunScythe','duneBow'],['prismSaber','jungleStaff'],['zenith','astralArmor']][id])owned.add(key);updatePack()}
function inLiquid(id){let x=Math.floor((p.x+p.w/2)/T);return get(x,Math.floor((p.y+p.h-2)/T))===id||get(x,Math.floor((p.y+12)/T))===id}
function updateSurvival(dt){harvestCooldown=Math.max(0,harvestCooldown-dt);hunger=Math.max(0,hunger-dt*(keys.shift&&Math.abs(p.vx)>20?.075:mount>=0?.04:.025));if(p.hp>0&&hunger>=16&&p.inv<=0&&!(oxygen<=0&&get(Math.floor((p.x+6)/T),Math.floor((p.y+5)/T))===8))p.hp=Math.min(100,p.hp+dt*(accessories.has('regenBand')?1.8:.8));else if(p.hp>0&&hunger<=0&&p.inv<=0&&!spawnProtectionActive())p.hp=Math.max(1,p.hp-dt*.35);if(inLiquid(9)&&weapon!=='flameFists'&&armor!=='obsidianArmor'&&!accessories.has('lavaCharm'))hurt(24);$('hunger-value').textContent=Math.ceil(hunger)+' / 20';$('hunger-bar').style.width=(hunger/20*100)+'%';drawMiniMap()}
function drawMiniMapBase(){const c=$('world-map').getContext('2d');c.clearRect(0,0,216,42);for(let i=0;i<3;i++){const b=biomes[i];c.fillStyle=b.color;c.fillRect(b.start/W*216,16,(b.end-b.start)/W*216,8)}c.font='9px monospace';c.textAlign='center';for(let i=0;i<3;i++){c.fillStyle='#e0e8d5';c.fillText(['FOREST','COAST','LAVA'][i],((biomes[i].start+biomes[i].end)/2)/W*216,11)}for(const w of wildMounts){c.fillStyle=tamed.has(w.id)?'#b7eaba':'#edc77d';c.fillRect(w.x/(W*T)*216-1,26,3,3)}c.fillStyle='#fff2c0';c.fillRect(Math.min(212,p.x/(W*T)*216)-2,14,4,12)}
function drawWorldExtras(){for(const f of forage){const x=f.x-camera.x,y=f.y-camera.y;if(x< -30||x>vw+30||y< -30||y>vh+30)continue;ctx.fillStyle=f.kind==='berries'?'#44704c':'#458b83';ctx.fillRect(x-9,y+2,20,10);ctx.fillRect(x-5,y-3,12,8);ctx.fillStyle=f.kind==='berries'?'#699b5d':'#78baa4';ctx.fillRect(x-7,y+1,4,3);ctx.fillRect(x+2,y+3,5,3);if(f.ready<=time){ctx.fillStyle=f.kind==='berries'?'#d79a9b':'#b5dcee';ctx.fillRect(x-4,y+2,3,3);ctx.fillRect(x+6,y+5,3,3);ctx.fillRect(x+1,y-2,3,3)}}}
function drawWildMounts(){for(const w of wildMounts){if(tamed.has(w.id))continue;const x=w.x-camera.x,y=w.y+(w.id===1?0:8)-camera.y;if(x< -60||x>vw+60)continue;mountSprite(ctx,w.id,x,y,w.face||1,false,w.vx||0,!w.ground);ctx.font='12px monospace';ctx.textAlign='center';ctx.fillStyle='#f3e7ba';ctx.fillText('T · '+trust[w.id]+'/3',x,y-38);ctx.textAlign='left'}}
function drawBiomeAtmosphereBase(b=biomeAt()){if(b===0)return;ctx.fillStyle=b===1?'#78b5c02c':'#a74e3540';ctx.fillRect(0,0,vw,vh);if(b===2){ctx.fillStyle='#674552';for(let j=0;j<3;j++){let x=j*420-(camera.x*.15)%420;ctx.beginPath();ctx.moveTo(x-140,vh*.8);ctx.lineTo(x+35,vh*.38);ctx.lineTo(x+60,vh*.4);ctx.lineTo(x+85,vh*.38);ctx.lineTo(x+260,vh*.8);ctx.fill();ctx.fillStyle='#bc7253';ctx.fillRect(x+38,vh*.4,42,5);ctx.fillStyle='#674552'}ctx.fillStyle='#da9d6755';for(let i=0;i<15;i++)ctx.fillRect((i*131+time*9-camera.x*.15)%(vw+100), (i*97-time*16+vh*100)%vh,2,2)}else{ctx.fillStyle='#679caf';ctx.fillRect(0,vh*.66,vw,vh*.34);ctx.fillStyle='#a6d3d9';for(let i=0;i<20;i++)ctx.fillRect((i*79-camera.x*.1+time*4)%(vw+80),vh*.68+i%5*11,26,2);ctx.fillStyle='#dae8df66';for(let i=0;i<8;i++){let x=(i*193+time*4-camera.x*.1)%(vw+100);ctx.fillRect(x,90+i%3*25,10,2)}}}

