function nearbyStation(id){return stations.some(s=>s.id===id&&Math.hypot(s.x+20-(p.x+6),s.y+10-(p.y+14))<=130)}
function stationLocation(){const tx=Math.floor(p.x/T),base=Math.floor((p.y+p.h+2)/T);for(const dx of [2,-3,4,-5]){const x=tx+dx;if(x<1||x>=W-3)continue;for(let y=base-1;y<=base+2;y++){if(solid(x,y)&&solid(x+1,y)&&!solid(x,y-1)&&!solid(x+1,y-1)&&![8,9].includes(get(x,y-1))&&!stations.some(s=>Math.abs(s.x-x*T)<40&&Math.abs(s.y-(y*T-20))<25)&&Math.hypot(x*T-p.x,y*T-p.y)<130)return {x:x*T,y:y*T-20}}}return null}
function craftOwned(r){return (r.item&&owned.has(r.item))||(r.kind==='pick'&&pick>=2)||(r.kind==='sword'&&sword===2)||(r.kind==='crystalpick'&&pick>=3)||(r.kind==='advancedpick'&&pick>=r.level)}
function craftBlockReason(r){if(r.kind==='pet'&&ownedPets.has(r.petId))return 'Owned';if(adminUnlocked&&admin.freeCraft)return r.kind==='station'&&!stationLocation()?'Needs flat ground nearby':'';if(craftOwned(r))return 'Owned';if(r.station&&!nearbyStation(r.station))return 'Needs '+stationDefs[r.station].name;if(r.kind==='station'&&!stationLocation())return 'Needs flat ground nearby';if(r.kind==='heal'&&p.hp>=100)return 'Health full';if(!(adminUnlocked&&admin.freeCraft)&&!Object.entries(r.cost).every(([k,v])=>(bag[k]||0)>=v))return 'Missing materials';return ''}
function refreshCraftBook(){if(!$('recipes'))return;$('recipes').innerHTML='';const active=Object.keys(stationDefs).filter(nearbyStation).map(k=>stationDefs[k].name);$('station-status').textContent='Nearby: '+(active.join(' · ')||'Hand crafting only');let shown=0;recipes.forEach((r,i)=>{if(craftCategory!=='All'&&r.category!==craftCategory)return;const searchable=(r.name+' '+r.detail+' '+Object.keys(r.cost).map(k=>materialNames[k]||k).join(' ')).toLowerCase();if(!searchable.includes(craftSearch.toLowerCase()))return;shown++;const row=document.createElement('div');row.className='recipe';const reason=craftBlockReason(r);row.innerHTML=`<div><strong>${r.name}</strong><small>${r.detail||r.category}${r.station?' · '+stationDefs[r.station].name:''}<br>${Object.entries(r.cost).map(([k,n])=>`${n} ${materialNames[k]||k} (${bag[k]||0}/${n})`).join(' · ')}</small></div><button ${reason?'disabled':''}>${reason|| (r.kind==='station'?'Build':'Craft')}</button>`;row.querySelector('button').onclick=()=>craft(i);$('recipes').appendChild(row)});if(!shown)$('recipes').textContent='No recipes match your search.';$('recipe-count').textContent=shown+' / '+recipes.length+' recipes';$('bag').textContent=Object.entries(bag).filter(([k,v])=>v>0).map(([k,v])=>`${v} ${materialNames[k]||foods[k]?.name||k}`).join(' · ')}
function updateBreath(dt){const submerged=get(Math.floor((p.x+p.w/2)/T),Math.floor((p.y+5)/T))===8,max=accessories.has('airTank')?45:20,rate=accessories.has('diveMask')?.5:1;for(const key of Object.keys(buffs))buffs[key]=Math.max(0,buffs[key]-dt);oxygen=Math.min(oxygen,max);if(submerged&&buffs.breath<=0)oxygen=Math.max(0,oxygen-dt*rate);else oxygen=Math.min(max,oxygen+dt*10);if(submerged&&oxygen<=0&&buffs.breath<=0){if(!spawnProtectionActive()&&!(adminUnlocked&&admin.god))p.hp-=dt*8;if(p.hp<=0)lastDeathCause='drowning';if(Math.floor(time*5)%3===0)burst(p.x+6,p.y,'#a8dce3',1)}$('oxygen-hud').classList[submerged||oxygen<max?'remove':'add']('hidden');$('oxygen-value').textContent=oxygen<=0?(spawnProtectionActive()?'SPAWN PROTECTED':'DROWNING!'):buffs.breath>0?'AIR POTION · '+Math.ceil(buffs.breath)+' s':Math.ceil(oxygen/rate)+' s';$('oxygen-bar').style.width=oxygen/max*100+'%';$('oxygen-bar').style.background=oxygen<max*.25?'#e88b76':'#a0d7e6'}
function usePotion(key){if(adminReckoning)return false;if(key==='recallPotion'&&activeArena){notify('The arena is sealed. Defeat the boss to leave.');return false}if(!started||!Object.hasOwn(potionDefs,key)||bag[key]<1||(key==='healPotion'&&p.hp>=100)){notify('No usable potion · Brew one at an Alchemy Table');return false}bag[key]--;potionChoice=key;if(key==='healPotion')p.hp=Math.min(100,p.hp+50);if(key==='airPotion'){buffs.breath=120;oxygen=accessories.has('airTank')?45:20}if(key==='speedPotion')buffs.speed=90;if(key==='guardPotion')buffs.defense=90;if(key==='recallPotion'){if(boss)bossCooldown(boss.id,75);boss=null;releaseArena();shots.length=0;resetNaturalEncounter();p.x=spawn.x;p.y=spawn.y;p.vx=p.vy=0;p.inv=2;oxygen=20}updatePack();notify(potionDefs[key]+' used');return true}
const potionDefs={healPotion:'Healing Potion · +50 health',airPotion:'Air Potion · 120 s underwater breathing',speedPotion:'Speed Potion · 90 s speed boost',guardPotion:'Guard Potion · 90 s extra defense',recallPotion:'Recall Potion · return to camp'};
function updateSupplies(){const el=$('supply-list');if(!el)return;el.innerHTML='';for(const [id,name]of Object.entries(potionDefs)){const row=document.createElement('div');row.className='recipe';row.innerHTML=`<div><strong>${name} × ${bag[id]}</strong><small>${potionChoice===id?'Selected · P to use':'Use once to select for the P shortcut'}</small></div><button ${bag[id]>0?'':'disabled'}>Use</button>`;row.querySelector('button').onclick=()=>usePotion(id);el.appendChild(row)}for(const id of [14,15,16,17,13]){const row=document.createElement('div');row.className='recipe';row.innerHTML=`<div><strong>${materialNames[id]} × ${bag[id]}</strong><small>Select, then right-click to place nearby</small></div><button ${bag[id]>0?'':'disabled'}>Select</button>`;row.querySelector('button').onclick=()=>{slots[7].id=id;slots[7].name=materialNames[id];select(7);closePanels()};el.appendChild(row)}}
function drawStationsBase(){for(const s of stations){const x=s.x-camera.x,y=s.y-camera.y;if(x< -80||x>vw+80||y< -50||y>vh+50)continue;ctx.fillStyle=stationDefs[s.id].color;ctx.fillRect(x,y+7,36,13);if(s.id==='bench'||s.id==='alchemy'){ctx.fillRect(x-2,y+4,40,5);ctx.fillStyle='#4f443e';ctx.fillRect(x+3,y+11,4,9);ctx.fillRect(x+29,y+11,4,9);if(s.id==='alchemy'){ctx.fillStyle='#b3dfd4';ctx.fillRect(x+8,y-6,6,11);ctx.fillStyle='#9ed494';ctx.fillRect(x+22,y-4,6,9)}}else if(s.id==='furnace'){ctx.fillRect(x+6,y-8,24,16);ctx.fillStyle='#30333b';ctx.fillRect(x+10,y+5,16,12);ctx.fillStyle='#edb65d';ctx.fillRect(x+13,y+9,10,6)}else if(s.id==='anvil'){ctx.fillRect(x-4,y+2,44,7);ctx.fillStyle='#40535c';ctx.fillRect(x+13,y+9,9,9)}else{ctx.fillStyle='#393d45';ctx.fillRect(x+3,y-5,30,15);ctx.fillStyle='#c5b894';ctx.fillRect(x+8,y-3,20,2)}ctx.font='12px monospace';ctx.textAlign='center';ctx.fillStyle='#e1e8d2';ctx.fillText(stationDefs[s.id].name,x+18,y-13);ctx.textAlign='left'}}
$('recipe-search').addEventListener('input',e=>{craftSearch=e.target.value;refreshCraftBook()});$('recipe-category').addEventListener('change',e=>{craftCategory=e.target.value;refreshCraftBook()});

// Natural encounters use active gameplay time; pausing does not advance them.
const nextBossSpawn=Array(biomes.length).fill(0),naturalEncounter={zone:-1,dwell:0,pending:-1,warning:0};let bossSafetyUntil=45;
function resetNaturalEncounter(){naturalEncounter.zone=-1;naturalEncounter.dwell=0;naturalEncounter.pending=-1;naturalEncounter.warning=0}
function bossCooldown(id,seconds){if(Number.isInteger(id)&&id>=0&&id<biomes.length)nextBossSpawn[id]=time+seconds;resetNaturalEncounter()}
function naturalSpawnEligible(){if(spawnProtectionActive())return false;if(skyTrial||adminReckoning||adminRevenge.warning>0)return false;if(p.y<0)return false;if((adminUnlocked&&!admin.naturalBosses)||!started||paused||boss||p.hp<=0||time<bossSafetyUntil)return false;const tile=Math.max(0,Math.min(W-1,Math.floor(p.x/T))),zone=biomeAt();if(p.y>surface[tile]*T-20||time<nextBossSpawn[zone])return false;if(zone===0&&Math.abs(p.x-spawn.x)<35*T)return false;const a=arenas[zone];if(a&&(p.x<a.left*T||p.x>a.right*T))return false;return true}
function updateNaturalBossSpawns(dt){if(!naturalSpawnEligible()){resetNaturalEncounter();return}const zone=biomeAt();if(naturalEncounter.zone!==zone){resetNaturalEncounter();naturalEncounter.zone=zone}if(naturalEncounter.pending<0){naturalEncounter.dwell+=dt;if(naturalEncounter.dwell>=20){naturalEncounter.pending=zone;naturalEncounter.warning=5;notify(bossDefs[zone].name+' is approaching in '+biomes[zone].name+'!');toastTimer=5;beep(130)}}else{naturalEncounter.warning=Math.max(0,naturalEncounter.warning-dt);if(naturalEncounter.warning<=0){resetNaturalEncounter();summon(zone);return}}
if(naturalEncounter.pending>=0){$('boss-hud').classList.remove('hidden');$('boss-name').textContent=bossDefs[zone].name+' approaches';$('boss-phase').textContent='Arriving in '+Math.ceil(naturalEncounter.warning)+' s · Leave the biome to avoid the fight';$('boss-health').style.width=(naturalEncounter.warning/5*100)+'%'}}
function naturalBossStatus(id){if(boss?.id===id)return 'Active encounter';if(time<nextBossSpawn[id])return 'Returns in '+Math.ceil(nextBossSpawn[id]-time)+' s';if(time<bossSafetyUntil)return 'The wilds are quiet · '+Math.ceil(bossSafetyUntil-time)+' s';if(id!==biomeAt())return 'Lingers in its arena naturally';if(naturalEncounter.pending===id)return 'Approaching · '+Math.ceil(naturalEncounter.warning)+' s';if(!naturalSpawnEligible())return id===0&&Math.abs(p.x-spawn.x)<35*T?'Explore beyond the safety of camp':'Explore the arena above ground';return 'Arena activity · '+Math.min(20,Math.floor(naturalEncounter.dwell))+' / 20 s'}

