const mounts=[{name:'Forest Hare',speed:240,jump:460,fly:false,color:'#bda286',detail:'Mosswood · feed 3 berries · fast runner & high jumps'},{name:'Moon Moth',speed:210,jump:350,fly:true,color:'#afc5e8',detail:'Tidal Coast · feed 3 nectar · hold jump to fly'},{name:'Ember Drake',speed:310,jump:450,fly:true,color:'#dc9a6c',detail:'Cinderlands · feed 3 grilled fish · defeat Ashwing first'}];
const bossDefs=[{name:'Moss King',hp:260,kind:0,color:'#89c67c',detail:'Leaps, spawns slimes, and hurls moss seeds.',reward:'Thorn Blade · Bark Armor · copper & wood'},{name:'Tide Warden',hp:360,kind:1,color:'#afd2ef',detail:'A coastal guardian that sends waves of water bolts.',reward:'Tidal Spear · Wind Glider · crystals & copper'},{name:'Ashwing',hp:480,kind:2,color:'#ea9e6a',detail:'A fire drake that dives and breathes flame.',reward:'Ember Bow · Obsidian Armor · drake taming unlocked'}];
function available(i){return tamed.has(i)}
function equipMount(i){if(!available(i)){notify('Find and tame this mount first. Press B for its food.');return;}mountChoice=i;mount=i;updateAdventure();notify('Riding '+mounts[i].name)}
function toggleMount(){if(adminReckoning)return false;if(mount<0)equipMount(mountChoice);else{mount=-1;notify('Dismounted');updateAdventure()}}
function cycleMount(){if(!tamed.size){notify('No tamed mounts yet · Feed a nearby creature with T');return}do{mountChoice=(mountChoice+1)%mounts.length}while(!available(mountChoice));if(mount>=0)equipMount(mountChoice);else notify(mounts[mountChoice].name+' selected · R to ride')}
function updateAdventure(){if(!$('boss-list'))return;updateRevengeGuide();$('boss-list').innerHTML='';bossDefs.forEach((d,i)=>{const row=document.createElement('div');row.className='recipe boss-entry';row.innerHTML=`<div><strong>${d.name}${defeated.has(i)?' · Defeated':''}</strong><small>${biomes[i].name} · ${biomeAt()===i?'You are here':'Travel east or west'}<br>${d.detail}<br>Reward: ${d.reward}<br><b>${naturalBossStatus(i)}</b></small></div>`;$('boss-list').appendChild(row)});$('mount-list').innerHTML='';mounts.forEach((m,i)=>{let unlocked=available(i),row=document.createElement('div');row.className='recipe';row.innerHTML=`<div><strong>${m.name}</strong><small>${m.detail}<br>${i===3?(unlocked?'Glitch bond established':'Admin summon / revenge reward'):'Trust: '+trust[i]+' / 3'+(unlocked?' · Tamed':'')}</small></div><button class="${!unlocked?'locked':mount===i?'equipped':''}" ${!unlocked?'disabled':''}>${!unlocked?(i===3?'Locked':'Untamed'):mount===i?'Dismount':'Ride'}</button>`;row.querySelector('button').onclick=()=>{mount===i?toggleMount():equipMount(i);closePanels()};$('mount-list').appendChild(row)})}
function dash(){if(adminReckoning)return false;if(dashCooldown>0||!started||paused)return false;dashTime=.18;dashCooldown=accessories.has('swiftBoots')?.7:1;dashDir=(keys.a||keys.arrowleft)?-1:(keys.d||keys.arrowright)?1:p.face;p.face=dashDir;p.inv=Math.max(p.inv,.22);beep(500);return true}
function movePlayer(dt){dashCooldown=Math.max(0,dashCooldown-dt);const jumping=!!(keys[' ']||keys.w||keys.arrowup),dir=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),m=mount>=0?mounts[mount]:null;
if(jumping&&!jumpWas)jumpBuffer=.13;else jumpBuffer=Math.max(0,jumpBuffer-dt);jumpWas=jumping;coyote=p.ground?.11:Math.max(0,coyote-dt);let speed=(m?m.speed:155)*(shadowFormActive()?1.2:1)*(adminUnlocked?admin.speed:1)*(keys.shift&&hunger>3?1.6:1)*(accessories.has('swiftBoots')?1.2:1)*(buffs.speed>0?1.3:1)*(waterStyleSurface()?1.25:inLiquid(8)&&!(m&&m.fly) ? .7 : 1),goal=dir*speed,accel=p.ground?1800:1100;p.vx+=Math.max(-accel*dt,Math.min(accel*dt,goal-p.vx));if(dir)p.face=dir;
if(codeInputFlightActive()){mount=-1;p.vx=dir*260*(keys.shift?1.3:1);p.vy=jumping?-260:(keys.s||keys.arrowdown)?260:0;physics(p,dt,0);p.y=Math.max(-SKY*T+5,p.y);jumpBuffer=0}else if(adminUnlocked&&admin.flight){p.vy=jumping?-240:(keys.s||keys.arrowdown)?240:0;physics(p,dt,0);p.y=Math.max(-SKY*T+5,p.y)}else if(dashTime>0){dashTime-=dt;p.vx=dashDir*(m?650:560);p.vy=0;trail.push({x:p.x,y:p.y,life:.22});physics(p,dt,0)}else if(m?.fly){const down=keys.s||keys.arrowdown;p.vy=jumping?-190:down?210:45;physics(p,dt,0);p.y=Math.max(-SKY*T+5,p.y);jumpBuffer=0}else{if(jumpBuffer>0&&coyote>0){p.vy=-(m?m.jump:360)*(adminUnlocked?admin.jump:1);coyote=0;jumpBuffer=0;beep(330)}if(!jumping&&p.vy< -150)p.vy+=1450*dt;if(accessories.has('glider')&&jumping&&p.vy>0){p.vy=Math.min(p.vy,65);physics(p,dt,0)}else if(inLiquid(8)){p.vy=jumping?(accessories.has('flippers')?-180:-100):Math.min(p.vy,95);physics(p,dt,120)}else physics(p,dt)}
$('mount-label').textContent=codeInputFlightActive()?'INPUT FLIGHT · W / Space up · S down':m?m.name+(m.fly?' · hold jump to fly':' · riding'):'On foot · Shift to sprint';$('dash-label').textContent=dashCooldown>0?'Dash · '+dashCooldown.toFixed(1)+' s':'Dash ready · Q'}
function rectDistance(a,b){let x=Math.max(b.x,Math.min(a.x+a.w/2,b.x+b.w)),y=Math.max(b.y,Math.min(a.y+a.h/2,b.y+b.h));return Math.hypot(x-(a.x+a.w/2),y-(a.y+a.h/2))}
function overlaps(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function summon(i){if(!started||boss||!bossDefs[i])return false;if(biomeAt()!==i){notify(bossDefs[i].name+' lives in '+biomes[i].name+'. Travel there first.');return false}let tile=Math.min(W-8,Math.max(7,Math.floor(p.x/T)));if(p.y>surface[tile]*T-20){notify('Summon bosses above ground in their home biome.');return false}const d=bossDefs[i],bx=Math.max(biomes[i].start*T+80,Math.min(biomes[i].end*T-140,p.x+(p.x<biomes[i].end*T-360?230:-230))),by=Math.min(...surface.slice(Math.floor(bx/T),Math.floor(bx/T)+5))*T;boss={...d,id:i,max:d.hp,x:bx,y:by-(i===0?50:160),w:(i===2?86:64)*admin.bossSize,h:(i===0?48:58)*admin.bossSize,vx:0,vy:0,ground:false,timer:1.4,age:0,hit:0,phase:1,dive:0,diveTimer:3};shots.length=0;sealArena(i);notify(d.name+' awakens!');beep(120);updateAdventure();return true}
function hurt(amount){if(spawnProtectionActive()||(adminUnlocked&&admin.god)||p.inv>0)return;if(codeWeapon.shieldUntil>time)amount*=.25;p.hp-=Math.max(2,amount-((armor?items[armor].defense:0)+(accessories.has('ironShield')?3:0)+(buffs.defense>0?4:0)+(styleGuardUntil>time?10:0)+(shadowFormActive()?6:0)));p.inv=1;p.vy=-150;burst(p.x,p.y,'#f09c81');beep(90)}
function damageBoss(amount,force=false){if(!boss||bossIntro&&!force)return;boss.hp-=amount*(adminUnlocked?admin.damage:1);boss.hit=.1;burst(boss.x+boss.w/2,boss.y+boss.h/2,boss.color,5);if(boss.hp<=0){if(boss.revenge){finishRevengeAdmin();return}const id=boss.id,name=boss.name;defeated.add(id);bossCooldown(id,180);grantLoot(id);if(id===0){bag[4]+=12;bag[3]+=25}else if(id===1){bag[5]+=8;bag[4]+=15}else bag[5]+=15;p.hp=100;boss=null;releaseArena();for(const shot of shots)if(shot.enemy)shot.life=0;inventory();updateAdventure();notify(name+' defeated! '+'New weapon and gear · Open G to equip.');beep(720)}}
function projectile(x,y,vx,vy,enemy,color,damage=12){shots.push({x,y,vx,vy,enemy,color,damage,life:3,w:enemy?8:14,h:enemy?8:6})}
function slash(){let a=p.face===1?0:Math.PI;if(mouse.active){let dx=mouse.x+camera.x-(p.x+6),dy=mouse.y+camera.y-(p.y+14);if(Math.hypot(dx,dy)>5){a=Math.atan2(dy,dx);p.face=dx>=0?1:-1}}const it=items[weapon];if(weapon==='lineOfCode'){codeMeleeSlash(a);return}if(styleDefs[weapon]){styleStrike(weapon,a);return}if(weapon==='zenith'){zenithAttack(a);return}const angles=weapon==='emberBow'||it.shape==='staff'?[-.12,0,.12]:weapon==='thornBlade'?[-.15,.15]:[0];for(const offset of angles){let angle=a+offset;projectile(p.x+6,p.y+14,Math.cos(angle)*it.speed,Math.sin(angle)*it.speed,false,it.color,it.damage);const shot=shots[shots.length-1];shot.life=it.shape==='spear'?.55:it.shape==='bow'?2:1.4;shot.w=it.shape==='spear'?20:it.shape==='bow'?12:14;shot.h=it.shape==='bow'?3:6;shot.kind=it.shape==='sword'?'airSlash':it.shape;shot.age=0;if(glitchDefs[weapon])shot.glitchId=weapon}}
