function tileDraw(c,v,x,y,size,tx=0,ty=0){const zone=biomeAt(tx*T),original=palette[v];if(drawEcologyTile(c,v,x,y,size,tx,ty))return;if([1,2,3,6].includes(v)&&zone>=3){const sets=[null,null,null,{1:['#b7d6df','#7b9da9','#e5f6f5'],2:['#758ca6','#4b617d','#a2bacd'],3:['#76868d','#4c606b','#a3c3cc'],6:['#adced8','#708f9a','#ecf6ed']},{1:['#c7a477','#9e7950','#ebca93'],2:['#aa8262','#715445','#d4a67c'],3:['#81915c','#5d6b3f','#b8c479'],6:['#809456','#556834','#bdc77e']},{1:['#647f58','#3b563f','#98b777'],2:['#5c7681','#39535e','#a2b9b7'],3:['#7b6754','#524c3c','#b3a773'],6:['#3d9c73','#24644e','#84d197']},{1:['#9384ae','#5f5579','#c8b3d7'],2:['#726687','#423d60','#b9a6cc'],3:['#8574a5','#544b73','#bbabd2'],6:['#917fc0','#5d528a','#d7bbef']}];palette[v]=sets[zone][v]}tileDrawBase(c,v,x,y,size,tx,ty);palette[v]=original;const a=zone>=3&&v===1?biomes[zone].color:original?.[2];if(!a||[8,9,16,17].includes(v))return;c.save();c.globalAlpha=.22;c.fillStyle=a;for(let j=0;j<7;j++){const n=hash(tx+j*13,ty+j*7);c.fillRect(x+2+Math.floor(n*(size-5)),y+2+Math.floor(hash(tx-j,ty+j*5)*(size-5)),j%3===0?3:2,1)}c.globalAlpha=.2;c.fillStyle='#101d2c';if(v===2||v===13){c.fillRect(x+2,y+8,size-5,1);c.fillRect(x+Math.floor(hash(tx,ty)*12)+3,y+9,1,6)}if(v===3||v===7){c.fillRect(x+7,y+4,3,1);c.fillRect(x+6,y+5,1,4)}if(v===6){c.fillRect(x+5,y+7,4,2);c.fillRect(x+12,y+12,5,2)}c.restore();if(zone===3&&v===1&&get(tx,ty-1)===0){c.fillStyle='#edf8fa';c.fillRect(x,y,size,4);c.fillRect(x+2,y+4,4,2)}if(zone===6&&v===5){c.fillStyle='#efcfff';c.fillRect(x+4,y+3,2,2)}}
