function styleEnemyHit(e,damage){if(e===boss){damageBoss(damage);return}const before=e.hp;if(before<=0)return;e.hp-=damage*(adminUnlocked?admin.damage:1);e.hit=.2;e.vx=Math.sign(e.x-p.x)*160;e.vy=-100;burst(e.x+e.w/2,e.y+e.h/2,styleDefs[weapon]?.color||'#ddd',5);if(e.hp<=0){kills++;slimeReward(e);p.hp=Math.min(100,p.hp+6)}}
