function drawEcologyTile(c,v,x,y,size,tx,ty){const zone=biomeAt(tx*T),d=biomeLife[zone];if(v===18){c.fillStyle=d.dark;c.fillRect(x,y,size,size);c.fillStyle='#243340';c.fillRect(x,y+size-3,size,3);c.fillRect(x+size-2,y,2,size);c.fillStyle=d.color;c.globalAlpha*=.45;c.fillRect(x+2,y+2,size-4,2);c.fillRect(x+4,y+8,3,2);c.globalAlpha/=.45;return true}if(v>=20&&v<=26){const ore=biomeLife[v-20];c.fillStyle='#4f5a6b';c.fillRect(x,y,size,size);c.fillStyle='#344252';c.fillRect(x,y+size-3,size,3);c.fillRect(x+2,y+10,8,1);c.fillStyle=ore.dark;c.fillRect(x+2,y+2,8,8);c.fillRect(x+10,y+9,7,7);c.fillStyle=ore.color;const gems=v%2===0;for(const [dx,dy]of [[4,3],[12,10]]){c.fillRect(x+dx,y+dy,gems?5:4,5);if(gems)c.fillRect(x+dx+1,y+dy-1,3,7);c.fillStyle='#f5f3dc';c.fillRect(x+dx+1,y+dy,2,1);c.fillStyle=ore.color}return true}if(v===3&&[1,2,4].includes(zone)){const colors=zone===1?['#aa9071','#766b51','#d4c6a0']:zone===2?['#605056','#3e383f','#ae7a66']:['#76935e','#4b6542','#b0c680'];c.fillStyle=colors[0];c.fillRect(x+2,y,size-4,size);if(zone===4){if(get(tx-1,ty)===3)c.fillRect(x,y+5,size/2,10);if(get(tx+1,ty)===3)c.fillRect(x+size/2,y+5,size/2,10)}c.fillStyle=colors[1];c.fillRect(x+5,y,2,size);c.fillRect(x+12,y,2,size);c.fillStyle=colors[2];c.fillRect(x+4,y+4,size-8,2);if(zone===4){c.fillRect(x+9,y+8,1,3);c.fillRect(x+15,y+14,2,2)}return true}if(v===6&&[1,2].includes(zone)){c.fillStyle=zone===1?'#4d9b80':'#d38351';c.fillRect(x,y,size,size);c.fillStyle=zone===1?'#82c4a6':'#ffd18c';c.fillRect(x+3,y+4,7,2);c.fillRect(x+12,y+12,4,2);return true}return false}

