function adminUnlockStyles(){requireAdmin();for(const id of Object.keys(styleDefs))owned.add(id);styleAbilityCooldown=0;adminCRecharge=adminRRecharge=0;updateStyles();updatePack();notify('All fighting styles learned · L to equip')}
function growTree(x,zone){const base=surface[x],h=[7,9,7,11,6,12,10][zone]+Math.floor(rand()*3),tiles=[],seen=new Set();const put=(dx,dy,v)=>{const tx=x+dx,ty=base+dy,key=tx+','+ty;if(tx<1||tx>=W-1||ty<0||ty>=surface[tx]||get(tx,ty)!==0&&get(tx,ty)!==6)return;if(seen.has(key)){const old=tiles.find(t=>t.x===tx&&t.y===ty);if(old?.v===3)return;if(old)old.v=v;set(tx,ty,v);return}set(tx,ty,v);seen.add(key);tiles.push({x:tx,y:ty,v})};
for(let j=1;j<=h;j++){put(zone===1?Math.floor(j/5):0,-j,3);if(zone===1&&j%5===0)put(Math.floor(j/5)-1,-j,3)}
if(zone===0||zone===5){const crown=zone===5?5:3;for(let dx=-crown;dx<=crown;dx++)for(let dy=-3;dy<=2;dy++)if(Math.abs(dx)+Math.abs(dy)<crown+2)put(dx,-h+dy,6);if(zone===5){for(let j=1;j<h-3;j++)put(1,-j,3);for(const dx of [-4,4])for(let j=0;j<4;j++)put(dx,-h+j+3,6)}}
if(zone===1){const lean=Math.floor(h/5);for(let dx=-5;dx<=5;dx++){put(lean+dx,-h+Math.floor(Math.abs(dx)/3),6);if(Math.abs(dx)>2)put(lean+dx,-h+2,6)}}
if(zone===2){for(const dx of [-1,1]){put(dx,-h+3,3);put(dx*2,-h+2,3);put(dx*2,-h+1,6)}put(0,-h-1,6)}
if(zone===3)for(let j=0;j<h-2;j++){const width=Math.min(4,Math.floor(j/3));for(let dx=-width;dx<=width;dx++)if(dx!==0)put(dx,-h+j,6)}
if(zone===4){for(const dx of [-2,2]){put(Math.sign(dx),-3,3);put(dx,-3,3);put(dx,-4,3);put(dx,-5,3)}}
if(zone===6){for(let dx=-4;dx<=4;dx++){put(dx,-h+Math.floor(Math.abs(dx)/2),6);for(let j=1;j<=3+Math.abs(dx)%3;j++)if(Math.abs(dx)>=2)put(dx,-h+j,6)}}
trees.push({x,base,zone,tiles,fallen:false})}
function fellTree(tx,ty){const tree=trees.find(t=>!t.fallen&&t.tiles.some(v=>v.x===tx&&v.y===ty&&v.v===3));if(!tree)return false;tree.fallen=true;const tiles=tree.tiles.filter(t=>get(t.x,t.y)===t.v);for(const t of tiles)set(t.x,t.y,0);const wood=tiles.filter(t=>t.v===3).length;bag[3]+=wood;fallingTrees.push({tree,tiles,age:0,dir:p.x<tree.x*T?1:-1});burst(tree.x*T,tree.base*T,biomeLife[tree.zone].color,10);notify(biomeLife[tree.zone].tree+' felled · +'+wood+' wood');inventory();return true}
function tickEcology(dt){for(let i=fallingTrees.length-1;i>=0;i--){const f=fallingTrees[i];f.age+=dt;if(f.age>=1.25){burst(f.tree.x*T+f.dir*70,f.tree.base*T,biomeLife[f.tree.zone].color,14);fallingTrees.splice(i,1)}}if(!boss&&activeArena)releaseArena();if(activeArena&&!bossIntro)keepArenaActors()}
function drawFallingTrees(){for(const f of fallingTrees){ctx.save();ctx.translate(f.tree.x*T+T/2-camera.x,f.tree.base*T-camera.y);ctx.rotate(f.dir*Math.min(Math.PI/2,Math.pow(f.age/.9,2)*Math.PI/2));ctx.globalAlpha=f.age>.9?Math.max(0,(1.25-f.age)/.35):1;for(const t of f.tiles)tileDraw(ctx,t.v,(t.x-f.tree.x)*T-T/2,(t.y-f.tree.base)*T,T,t.x,t.y);ctx.restore()}}
function slimeReward(s){if(s.rewarded)return;s.rewarded=true;if(s.species){bag[20+s.zone]=(bag[20+s.zone]||0)+2;if(s.zone===0||s.zone===5)bag.berries+=2;else if(s.zone===1)bag.fish+=1;else if(s.zone===3||s.zone===6)bag[5]+=1;return}bag.gel+=2;if(Number.isInteger(s.zone))bag[20+s.zone]=(bag[20+s.zone]||0)+1}
function slimeSpecial(s,dt){const zone=s.zone??0;if(![1,2,3,5,6].includes(zone)||Math.abs(s.x-p.x)>340)return;s.spell=(s.spell??2)-dt;if(s.spell>0)return;s.spell=zone===6?3.8:3.3;const d=biomeLife[zone],a=Math.atan2(p.y-s.y,p.x-s.x),count=zone===5?3:zone===6?5:1;for(let j=0;j<count;j++){const angle=a+(j-(count-1)/2)*.15;projectile(s.x+11,s.y+5,Math.cos(angle)*170,Math.sin(angle)*170,true,d.color,zone===6?12:8)}}
function drawBiomeSlime(s){if(s.species){drawRegionalEnemy(s);return}const zone=s.zone??biomeAt(s.x),d=biomeLife[zone],x=Math.round(s.x-camera.x),y=Math.round(s.y-camera.y);ctx.save();ctx.translate(x,y);ctx.scale(admin.slimeSize,admin.slimeSize);ctx.fillStyle=s.hit>0?'#fff7d5':d.color;ctx.fillRect(3,0,16,3);ctx.fillRect(0,3,22,12);ctx.fillStyle=d.dark;ctx.fillRect(0,12,22,3);ctx.fillStyle='#f6ffe466';ctx.fillRect(4,3,7,3);ctx.fillRect(2,6,2,3);ctx.fillStyle='#233936';ctx.fillRect(5,7,2,3);ctx.fillRect(15,7,2,3);ctx.fillStyle='#f0edd3';if(zone===0){ctx.fillStyle='#aacb72';ctx.fillRect(9,-4,5,4)}if(zone===1){ctx.strokeStyle='#e0faff';ctx.lineWidth=1;ctx.beginPath();ctx.arc(11,6,7,0,Math.PI*2);ctx.stroke()}if(zone===2){ctx.fillStyle='#ffdb86';ctx.fillRect(5,-4,3,5);ctx.fillRect(13,-6,4,7)}if(zone===3){for(let j=0;j<3;j++){ctx.fillStyle='#f0fbff';ctx.fillRect(3+j*6,-5,3,6)}}if(zone===4){ctx.fillStyle='#b98e5d';ctx.fillRect(-2,2,26,3);ctx.fillStyle='#f8e6b5';ctx.fillRect(8,-2,7,4)}if(zone===5){ctx.fillStyle='#e3c2fc';ctx.fillRect(8,-7,6,8);ctx.fillRect(3,-3,3,5);ctx.fillRect(16,-3,3,5)}if(zone===6){ctx.fillStyle='#fff0be';ctx.fillRect(9,-6,4,10);ctx.fillRect(6,-3,10,4);ctx.fillStyle='#eee5ff';ctx.fillRect(8,10,6,2)}ctx.restore()}
function buildArena(id){const center=[115,344,605,990,1530,2070,2610][id],floor=Math.max(28,surface[center]),left=center-18,right=center+18,top=Math.max(3,floor-20),a={id,center,left,right,top,floor,color:biomeLife[id].color,name:['Verdant Ring','Pearl Coliseum','Ember Crucible','Glacier Sanctum','Sunscar Pit','Prism Court','Astral Throne'][id]};arenas.push(a);for(let x=left-2;x<=right+2;x++){surface[x]=floor;for(let y=top-3;y<floor;y++)set(x,y,0);for(let y=floor;y<floor+3;y++)set(x,y,18)}for(const y of [floor-5,floor-10])for(const dx of [-12,6])for(let j=0;j<6;j++)set(center+dx+j,y,17);for(const t of trees)if(t.tiles.some(v=>v.x>=left-2&&v.x<=right+2)){t.fallen=true;for(const v of t.tiles)if(get(v.x,v.y)===v.v)set(v.x,v.y,0)}for(const s of slimes)if(s.x>left*T&&s.x<right*T)s.hp=0}
function arenaProtected(x,y){return arenas.some(a=>x>=a.left-2&&x<=a.right+2&&y>=a.top-3&&y<=a.floor+2)}
function arenaWall(x,y){const a=activeArena;if(!a)return false;return x>=a.left&&x<=a.right&&(y===a.top||y>=a.floor)||y>=a.top&&y<=a.floor&&(x===a.left||x===a.right)}
function sealArena(id){adminBarrage=null;styleEffects.length=0;styleGuardUntil=0;const a=arenas[id];activeArena=a;bossIntro={id,age:0,duration:3.6};p.x=(a.center-9)*T;p.y=a.floor*T-p.h;p.vx=p.vy=0;p.attack=0;p.inv=1;keysClear();mount=-1;if(activePet){activePet.x=p.x-35;activePet.y=p.y}for(const s of slimes)if(s.x>a.left*T&&s.x<a.right*T)s.hp=0;if(boss){boss.x=(a.center+6)*T;boss.y=a.floor*T-boss.h;boss.vx=boss.vy=0}closePanels();$('skip-intro').classList.remove('hidden');$('boss-hud').classList.remove('hidden');$('boss-name').textContent=boss.name;$('boss-phase').textContent='ENTRANCE · Arena sealed';$('boss-health').style.width='100%';notify(a.name+' sealed · Defeat the boss to leave')}
function releaseArena(){adminBarrage=null;activeArena=null;bossIntro=null;$('skip-intro').classList.add('hidden')}
function finishBossIntro(){if(!bossIntro)return false;bossIntro=null;$('skip-intro').classList.add('hidden');if(boss){boss.x=(activeArena.center+6)*T;boss.y=activeArena.floor*T-boss.h-(boss.kind===0||boss.kind===3||boss.kind===4?0:100);boss.timer=1.4;boss.diveTimer=3}p.inv=1;notify('Fight! Defeat '+(boss?.name||'the boss')+' to open the gates');return true}
function tickBossIntro(dt){if(!bossIntro||!boss){releaseArena();return}const intro=bossIntro,a=activeArena;intro.age+=dt;const t=Math.min(1,intro.age/intro.duration),floor=a.floor*T;boss.x=(a.center+6)*T;boss.y=floor-boss.h;if(intro.id===0)boss.y+=Math.max(0,1-t*1.8)*55;if(intro.id===1)boss.y+=Math.max(0,1-t*1.7)*95-50;if(intro.id===2){boss.x=(a.center+6)*T+(1-t)*180;boss.y=floor-boss.h-70-(1-t)*250}if(intro.id===3)boss.y-=Math.max(0,1-t*2)*130;if(intro.id===4)boss.y+=Math.max(0,1-t*1.9)*80;if(intro.id===5){boss.x+=(1-t)*Math.cos(t*12)*110;boss.y-=70+(1-t)*Math.sin(t*12)*70}if(intro.id===6)boss.y-=80+(1-t)*190;if(Math.floor(intro.age*20)%4===0)burst(boss.x+boss.w/2,boss.y+boss.h/2,a.color,2);if(t>=1)finishBossIntro()}
function keepArenaActors(){const a=activeArena;if(!a)return;for(const o of [p,...(boss?[boss]:[]),...(activePet?[activePet]:[])]){o.x=Math.max((a.left+1)*T,Math.min(a.right*T-o.w,o.x));o.y=Math.max((a.top+1)*T,Math.min(a.floor*T-o.h,o.y))}}
function drawArenaBackground(){for(const a of arenas){const x=a.left*T-camera.x,y=a.top*T-camera.y,w=(a.right-a.left+1)*T,h=(a.floor-a.top)*T;if(x+w<0||x>vw)continue;ctx.save();ctx.fillStyle=['#233e335c','#25445177','#442f3477','#2f4b6577','#59432e77','#3f345877','#39324d99'][a.id];ctx.fillRect(x,y,w,h);ctx.strokeStyle=a.color+'44';ctx.lineWidth=2;for(let j=0;j<5;j++){const px=x+50+j*(w-100)/4;ctx.fillStyle=a.color+'33';ctx.fillRect(px,y+40,16,h-40);ctx.fillStyle=a.color+'77';ctx.fillRect(px-5,y+36,26,5);if(a.id===0||a.id===5){ctx.fillStyle=a.id===0?'#71a96355':'#ae86d555';for(let k=0;k<7;k++)ctx.fillRect(px+(k%2)*6,y+60+k*30,5,14)}if(a.id===3){ctx.fillStyle='#d1f4ff66';ctx.fillRect(px-5,y+1,6,25+j%3*12)}if(a.id===2){ctx.fillStyle='#ffb87577';ctx.fillRect(px-6,y+h-24,28,4);ctx.fillRect(px+2,y+h-35-Math.sin(time*6+j)*4,10,14)}if(a.id===4){ctx.fillStyle='#e4c17e77';ctx.fillRect(px-3,y+24,22,16);ctx.fillRect(px+3,y+17,10,8)}}ctx.beginPath();ctx.arc(x+w/2,y+h*.7,68,0,Math.PI*2);ctx.stroke();if(a.id===1){ctx.strokeStyle='#9ce6f777';for(let j=0;j<3;j++){ctx.beginPath();ctx.arc(x+w/2,y+h*.65,45+j*25,0,Math.PI);ctx.stroke()}}if(a.id===6){for(let j=0;j<15;j++){const px=x+40+(j*83)%(w-80),py=y+20+(j*47)%(h-60);ctx.fillStyle='#e6ddf2aa';ctx.fillRect(px,py,3,3);if(j>0){ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(px-35,py-15);ctx.stroke()}}}ctx.font='15px monospace';ctx.textAlign='center';ctx.fillStyle=a.color;ctx.fillText(a.name.toUpperCase(),x+w/2,y+25);ctx.font='10px monospace';ctx.fillText(activeArena?.id===a.id?'SEALED · VICTORY OPENS THE GATES':'BOSS TERRITORY · LINGER HERE TO CHALLENGE',x+w/2,y+43);ctx.restore()}}
function drawArenaSeal(){const a=activeArena;if(!a)return;ctx.save();ctx.strokeStyle=a.color;ctx.fillStyle=a.color+'66';ctx.lineWidth=3;const left=(a.left+1)*T-camera.x,right=a.right*T-camera.x,top=(a.top+1)*T-camera.y,bottom=a.floor*T-camera.y;ctx.fillRect(left-20,top,20,bottom-top);ctx.fillRect(right,top,20,bottom-top);ctx.fillRect(left-20,top-20,right-left+40,20);for(const x of [left-10,right+10]){ctx.beginPath();for(let y=top;y<=bottom;y+=8){const xx=x+Math.sin(y*.07+time*5)*4;if(y===top)ctx.moveTo(xx,y);else ctx.lineTo(xx,y)}ctx.stroke()}ctx.restore()}
function drawBossIntro(){if(!bossIntro||!boss)return;if(boss.revenge){drawRevengeIntro();return}const i=bossIntro.id,t=bossIntro.age/bossIntro.duration,a=activeArena,x=boss.x+boss.w/2-camera.x,y=boss.y+boss.h/2-camera.y;ctx.save();ctx.fillStyle='#061020aa';ctx.fillRect(0,0,vw,55);ctx.fillRect(0,vh-80,vw,80);ctx.strokeStyle=a.color;ctx.fillStyle=a.color;ctx.lineWidth=3;if(i===0){for(let j=0;j<7;j++)ctx.fillRect(x-110+j*32,y+50,4,25+Math.sin(t*8+j)*20)}if(i===1){for(let j=0;j<3;j++){ctx.beginPath();ctx.arc(x,y+50,35+(t*100+j*30)%100,Math.PI,Math.PI*2);ctx.stroke()}}if(i===2){for(let j=0;j<12;j++)ctx.fillRect(x+35+j*12,y-25-j*10,3,3)}if(i===3){for(let j=0;j<12;j++){const angle=j/12*Math.PI*2;ctx.fillRect(x+Math.cos(angle)*t*120,y+Math.sin(angle)*t*100,5,12)}}if(i===4){for(let j=0;j<16;j++)ctx.fillRect(x+Math.cos(j)*t*160,y+60-Math.sin(j)*t*70,5,3)}if(i===5){for(let j=0;j<8;j++){const angle=j*Math.PI/4+t*7;ctx.fillRect(x+Math.cos(angle)*75,y+Math.sin(angle)*75,7,7)}}if(i===6){ctx.beginPath();ctx.arc(x,y,90*(1-t)+15,0,Math.PI*2);ctx.stroke();for(let j=0;j<6;j++){const angle=j*Math.PI/3-t*5;ctx.beginPath();ctx.moveTo(x+Math.cos(angle)*110,y+Math.sin(angle)*110);ctx.lineTo(x,y);ctx.stroke()}}ctx.textAlign='center';ctx.fillStyle='#eee8ce';ctx.font='bold 22px monospace';ctx.fillText(boss.name.toUpperCase(),vw/2,vh-47);ctx.font=Math.max(8,Math.min(12,vw/60))+'px monospace';ctx.fillStyle=a.color;ctx.fillText(['Roots rise. The forest crowns its king.','The tide answers its ancient guardian.','A burning wing blots out the sun.','The glacier fractures. Its heart awakens.','Something immense stirs beneath the sand.','Crystal petals converge into a crown.','The stars descend. The final throne awakens.'][i],vw/2,vh-23);ctx.restore()}

let adminCRecharge=0,adminRRecharge=0,adminBarrage=null;
function equipAdminStyle(){requireAdmin();if(!started){notify('Enter the wilds first');return false}owned.add('omniFists');equipItem('omniFists');closePanels();notify('Omni Fists equipped · F attack · C Reality Collapse · R Starfall');return true}
function adminStyleReady(){return started&&!paused&&!bossIntro&&p.hp>0&&adminUnlocked&&weapon==='omniFists'&&owned.has('omniFists')}
function adminStylePose(){p.attack=.3;p.attackDuration=.3;p.attackWeapon='omniFists';p.attackAim=aimAngle();p.swingIndex++;beep(680)}
function useAdminCAbility(){if(adminReckoning)return false;if(!adminStyleReady())return false;if(adminCRecharge>0){notify('Reality Collapse recharging · '+Math.ceil(adminCRecharge)+'s');return false}adminCRecharge=8;adminStylePose();styleEffect('cosmic','#edceff',1000,1);for(const e of styleTargets(1000))styleEnemyHit(e,2500);p.hp=100;p.inv=Math.max(p.inv,4);updateStyleHud();notify('Reality Collapse · 2,500 damage · health restored');return true}
function useAdminRAbility(){if(adminReckoning)return false;if(!adminStyleReady())return false;if(adminRRecharge>0){notify('Starfall recharging · '+Math.ceil(adminRRecharge)+'s');return false}adminRRecharge=5;adminStylePose();adminBarrage={remaining:12,timer:0,x:mouse.active?mouse.x+camera.x:p.x+p.face*130,y:mouse.active?mouse.y+camera.y:p.y+p.h/2};updateStyleHud();notify('Starfall · 12 crushing strikes · 900 damage each');return true}
function handleRideKey(){if(weapon==='lineOfCode')return useCodeAbility('input');if(weapon==='shadowFists')return useShadowTransformation();if(weapon==='omniFists')return useAdminRAbility();toggleMount();return true}
function tickAdminStyle(dt){adminCRecharge=Math.max(0,adminCRecharge-dt);adminRRecharge=Math.max(0,adminRRecharge-dt);if(!adminBarrage)return;if(!adminUnlocked||p.hp<=0){adminBarrage=null;return}const cast=adminBarrage;cast.timer-=dt;while(cast.remaining>0&&cast.timer<=0){cast.remaining--;cast.timer+=.08;const targets=styleTargets(1000).sort((a,b)=>rectDistance(p,a)-rectDistance(p,b)),target=targets[0];let x=target?target.x+target.w/2:cast.x+(cast.remaining%3-1)*45,y=target?target.y+target.h/2:cast.y;if(activeArena){x=Math.max((activeArena.left+2)*T,Math.min((activeArena.right-1)*T,x));y=Math.max((activeArena.top+2)*T,Math.min(activeArena.floor*T-10,y))}styleEffects.push({kind:'meteor',color:['#ffc995','#b5eaff','#e3b6ff'][cast.remaining%3],x,y,radius:130,life:.85,maxLife:.85,power:1+(12-cast.remaining)/12,tilt:(cast.remaining%3-1)*.16});if(cast.remaining===0)styleEffects.push({kind:'starfallFinale',x,y,color:'#e9ceff',radius:190,life:1.1,maxLife:1.1});for(const e of targets)if(Math.hypot(e.x+e.w/2-x,e.y+e.h/2-y)<130)styleEnemyHit(e,900);burst(x,y,'#e9cbff',8);if(adminBarrage!==cast){if(cast.remaining>0&&p.hp>0)styleEffects.push({kind:'starfallFinale',x,y,color:'#e9ceff',radius:190,life:1.1,maxLife:1.1});break}}if(cast.remaining<=0)adminBarrage=null}

