function drawFistWeapon(c,id,pose,active){const d=styleDefs[id];if(id==='omniFists'){drawFloatingFists(c,pose,active,active?1-p.attack/p.attackDuration:1);return}c.save();c.translate(Math.round(pose.x),Math.round(pose.y));c.rotate(pose.angle);c.scale(admin.weaponSize,admin.weaponSize);drawHand(c,d.color,id==='waterFists'||id==='frostFists'?'palm':'fist');const frame=Math.floor(animationClock()*10);if(id==='flameFists'){sprite(c,['...f..f...','..fHffHf..','.fHHHHHHf.','..ffffff..'],{f:'#ef8159',H:'#ffdb91'},-5,-11-frame%2)}if(id==='frostFists'){sprite(c,['..i...i...','.ihi.ihi..','..iiiii...'],{i:'#81bedb',h:'#effaff'},-3,-10)}if(id==='stoneFists'){c.fillStyle='#a48d77';c.fillRect(1,-1,2,4);c.fillRect(5,-4,1,4)}if(id==='thunderFists'){c.fillStyle='#ffed96';for(let j=0;j<3;j++)c.fillRect(8+j*2,-6+j*3,3,2)}if(active){for(let j=3;j>0;j--){c.save();c.translate(-j*7,Math.sin(frame+j)*2);c.globalAlpha=.25-j*.05;drawHand(c,d.color,id==='waterFists'||id==='frostFists'?'palm':'fist');c.restore()}c.globalAlpha=.8;c.fillStyle='#fff3d3';c.fillRect(14,-6,3,2);c.fillRect(16,-1,4,2);c.fillRect(13,5,3,2)}c.restore()}
function drawFloatingFists(c,pose,active,t=1,aim=pose.angle){const clock=animationClock(),strike=meleeMotion(t).strike,which=p.swingIndex%2;for(let hand=0;hand<2;hand++){const idleX=hand?22:-19,idleY=hand?-21:-10,hover=Math.round(Math.sin(clock*4+hand*2)*3),punch=active&&(hand===which||p.attackDuration===.3)?strike:0,x=Math.round(idleX+Math.cos(aim)*punch*38),y=Math.round(idleY+hover+Math.sin(aim)*punch*28);c.save();c.translate(x,y);c.rotate(aim*(active?.8:.15)+(hand?-.18:.15));c.scale(admin.weaponSize*(hand?1:1.1),admin.weaponSize*(hand?1:1.1));if(punch>.05)for(let j=3;j>0;j--){c.save();c.translate(-j*6,0);c.globalAlpha=.12*(4-j);drawHand(c,'#9a86cf','fist',true);c.restore()}drawHand(c,hand?'#cdbcf5':'#9edbfa','fist',true);c.fillStyle='#ffe7ab';c.fillRect(-2,-10,2,3);c.fillRect(2,-12,2,4);c.fillRect(6,-10,2,3);c.restore();}c.fillStyle='#dab3f1';for(let j=0;j<4;j++){const angle=clock*1.4+j*Math.PI/2,x=Math.round(Math.cos(angle)*22),y=Math.round(-14+Math.sin(angle)*21);c.fillRect(x,y,2,2)}}
