function drawDragon(c,clock,big=false,speed=0,airborne=false){c.save();if(big)c.scale(1.7,1.7);drawDrakeLegs(c,creatureStep(speed,clock),airborne);dragonWing(c,clock);sprite(c,['............................oo..........','...........................ohho.........','.....................oo...ohhco.........','....................ohho.o cccco........','....................occcooo cccooo......','......ooo..........o cccccccccccccoo....','.....ohc cooooooooocccccccccehcccccco...','....ohcccccccccccccccccccccceecccccooo.','...ohcccccccccccccccccccccccccccccchho.','..ohcccccccccccccccccccccccccccccccco..','.ohccccccccccccccccchhhhhhhhhccccc oo..','ohccccccccccccccchhhhhhhhhhhhcccooo.....','occcccccccccccchhhhhhhcccooooooo........','.ooocccccccccccccccccooo................','....ooooooooooooooooo...................'],{o:'#4e3540',c:'#cb8862',h:'#f1c790',e:'#294443'},-27,-22);c.fillStyle='#784747';for(let j=0;j<7;j++)c.fillRect(-18+j*5,-15+(j%2)*3,2,2);c.fillStyle='#e8b575';for(let j=0;j<5;j++)c.fillRect(-18+j*6,-18,3,5);c.restore()}
function drawBossSprite(c,b){if(b.revenge){drawRevengeAdmin(c,b);return}const clock=animationClock()*(b.phase===2?1.3:1),face=p.x>b.x+b.w/2?1:-1;c.save();c.translate(32,29);if(b.kind===2)c.scale(face,1);const bob=Math.round(Math.sin(clock*3)*2);if(b.kind===0){c.save();c.translate(-32,-25);const squeeze=b.ground?Math.sin(clock*5)*.035:-.05;c.translate(32,44);c.scale(1+squeeze,1-squeeze);c.translate(-32,-44);pixelOval(c,0,2,64,46,'#283d43');pixelOval(c,2,4,60,42,'#67955f');pixelOval(c,4,5,55,35,'#96c578');for(let j=0;j<16;j++){c.fillStyle=j%2?'#52865b':'#bdd991';c.fillRect(5+(j*17)%51,12+(j*7)%26,3,2)}sprite(c,['g...g...g...g','gh..gh..gh..g','ghgghhgg hhggg','g hhhhhhhhh g','ggggggggggggg'],{g:'#c3a55c',h:'#fae7a0'},17,-6);c.fillStyle='#26383b';c.fillRect(15,20,7,5);c.fillRect(42,20,7,5);c.fillStyle='#edf0c8';c.fillRect(17,20,2,2);c.fillRect(44,20,2,2);c.fillStyle='#3f5543';c.fillRect(25,29,14,3+Math.round(Math.abs(Math.sin(clock*3))*2));c.fillStyle='#c0d690';c.fillRect(29,30,5,1);for(let j=0;j<5;j++){c.fillStyle='#3d7550';c.fillRect(5+j*12,39,7,6);c.fillStyle='#7bad6b';c.fillRect(6+j*12,39,2,5)}c.restore()}
if(b.kind===1){c.translate(0,bob);for(let j=0;j<3;j++){c.fillStyle=['#42768c','#67acc1','#a3d9e7'][j];const offset=Math.round(Math.sin(clock*3+j)*5);c.fillRect(-29+j*4,-2+offset,5,27-j*4);c.fillRect(24-j*3,-2-offset,5,27-j*4)}sprite(c,[
'..........gg..........','.........ghhg.........','.....ggggghhggggg.....','....oghhhhhhhhhhgo....','....ogccccccccccgo....','....occhccccchccco....','.....oceecccceeco.....','.....occchhhcccco.....','......occhhcccco......','.......occcccco.......','....ooooccccccoooo....','...ochhccccccchhhco...','..ochhhccggcchhhhco...','..occhhcghhgcchhcco...','...occcchhh hcccco....','....occcchhhccccco....','.....occcccccccco.....','......occcccccco......','.....occcccccccco.....','....occcccccccccco....','...occccchhhhccccco...','..occccchhhhhhccccco..','...ooooo....ooooo.....'],{o:'#293c59',c:'#8cc2d8',h:'#d9f1ed',g:'#d9c98f',e:'#2a4055'},-22,-31,2);c.save();c.translate(29,2);c.rotate(Math.sin(clock*2)*.1);c.fillStyle='#d2d8aa';c.fillRect(0,-30,3,60);c.fillRect(-8,-29,19,3);c.fillRect(-8,-39,3,12);c.fillRect(8,-39,3,12);c.fillRect(0,-44,3,16);c.restore()}
if(b.kind===2){c.translate(6,9);c.rotate(b.dive>0?.18:Math.sin(clock*2)*.04);drawDragon(c,clock,true,b.vx||0,true);if(b.phase===2){c.fillStyle='#ffdf9c';c.fillRect(47,2,6,3);c.fillRect(54,1,3,3)}}
if(b.kind===3){const step=creatureStep(b.vx||0,clock);for(let leg=0;leg<2;leg++){c.save();c.translate((leg?8:-10)+(leg?-step:step),-7);sprite(c,['ooooooo','ochhhco','occccco','occccco','ochccco','occccco','occccco','occcccco','oooooooo'],{o:'#30425d',c:'#7fabc4',h:'#ceeaf6'},-7,0,2);c.restore()}sprite(c,['.......ooooooo........','......ochhhhhco.......','......occccccco.......','......occececco.......','......occ cccco.......','.......occccc o.......','....ooooccccc oooo....','...ochhhhccchhhhcco...','..ochccccccccccchcco..','..occcccchccccccccco..','...occcchhhccccccco...','....occcchccccccco....','.....occcccccccco.....','......ooooooooo.......'],{o:'#2c3e59',c:'#99bfd5',h:'#e5f7f6',e:'#5d7f9b'},-22,-31,2);for(const side of [-1,1]){c.save();c.translate(side*28,-5+Math.round(Math.sin(clock*4+side)*3));c.rotate(side*.18);drawHand(c,'#a4cadc','fist');c.restore()}c.fillStyle='#62a7d4';c.fillRect(-2,-5,4,10);c.fillStyle='#f5ffff';c.fillRect(-1,-5,2,7)}
if(b.kind===4){c.translate(8,5);c.scale(face,1);for(let j=6;j>=0;j--){const x=-j*10,y=Math.round(Math.sin(clock*5+j*.6)*5);pixelOval(c,x-8,y-10,22,22,'#564757');pixelOval(c,x-6,y-8,18,18,j%2?'#b99060':'#d5b078');c.fillStyle='#f3d49a';c.fillRect(x-4,y-7,12,2);c.fillStyle='#78634c';c.fillRect(x-4,y+5,11,2);c.fillStyle='#e5c384';c.fillRect(x-1,y-14,4,6)}sprite(c,['.......ooooooo.......','......ohhhhhcco......','.....ohhccccccco.....','....ohcccccccccco....','...ohcccccchccccco...','...occcccceeeccccoo..','..occcccccceecchhhco.','..occcccccccccchhhco.','...occccoooooooocco..','....occoghgghgghgo...','.....ocoggggggggo....','......oooooooooo.....'],{o:'#584254',c:'#d9af73',h:'#f3d398',g:'#f6e9bd',e:'#273c48'},0,-19,2)}
if(b.kind===5){c.save();c.translate(0,-5+bob);c.scale(1.5,1.5);mothWing(c,-1,clock,true);mothWing(c,1,clock,true);c.restore();sprite(c,['........ggg........','.......ghhhg.......','....ggghhhhhggg....','.....ghhhhhhhg.....','......ohhhhho......','......occceco......','......occchco......','.......occco.......','.......ohhho.......','.....ooccccco......','....occcccccco.....','....occhhhccco.....','.....occgcco.......','......ocgco........','.....occgcco.......','....occchccco......','...occcchcccc o....','..occcchhhccccco...','...ooooooooooo....'],{o:'#433953',c:'#b490d7',h:'#edd6f1',g:'#d5bb7f',e:'#303854'},-19,-31+bob,2);c.fillStyle='#a2e6c5';c.fillRect(-4,-3+bob,8,3)}
if(b.kind===6){c.translate(0,bob);for(let j=0;j<6;j++){const a=clock*1.3+j*Math.PI/3;c.save();c.translate(Math.round(Math.cos(a)*45),Math.round(Math.sin(a)*29-6));c.rotate(a+Math.PI/2);sprite(c,['...h...','..hch..','..hch..','..hch..','..hch..','.ggggg.','...g...'],{h:'#f3e3b9',c:j%2?'#a9e8f2':'#d8b6ef',g:'#b99872'},-3,-7);c.restore()}sprite(c,['..g...g...g...g..','..gh..gh..gh..g..','..ghgghhgg hhggg..','..ggggggggggggg..','....ohhhhhhho....','....occccccco....','....oceccceco....','....occc hcco....','.....occccc o....','....ooccccc oo...','...occcchccccco..','..occccghgccccco.','.occccghhhgccccco','..occchhhhhhccco.','...occchhhhccco..','....occchhccco...','...occcchhcccc o.','..occccchhccccco.','.occccchhhhccccco','occcccchhhhcccccco','occccchhhhhhccccco','oooooooooooooooooo'],{o:'#34354f',c:'#8977b8',h:'#dacbec',g:'#e2c591',e:'#c6eff9'},-18,-34,2);c.fillStyle='#effbff';c.fillRect(-3,-7,6,8);c.fillStyle='#a0cfef';c.fillRect(-1,-5,2,4)}
if(b.hit>0){c.globalAlpha=.3;c.fillStyle='#ffefd0';pixelOval(c,-27,-20,54,42,'#ffefd0')}c.restore()}
function drawCombat(){for(const t of trail){ctx.fillStyle=`rgba(187,235,213,${t.life*2})`;ctx.fillRect(t.x-camera.x,t.y-camera.y,13,29)}if(boss){ctx.save();ctx.translate(Math.round(boss.x-camera.x),Math.round(boss.y-camera.y));ctx.scale(admin.bossSize,admin.bossSize);drawBossSprite(ctx,boss);ctx.restore()}for(const s of shots){if(s.codeShot)drawCodeShot(s);else if(s.glitchId)drawGlitchShot(s);else if(s.styleId)drawElementalProjectile(s);else if(s.kind==='airSlash')drawAirSlash(s);else if(s.kind==='fist')drawStyleProjectile(s);else drawPremiumProjectile(s)}}
function drawStyleProjectile(s){ctx.save();ctx.translate(Math.round(s.x-camera.x),Math.round(s.y-camera.y));ctx.rotate(Math.atan2(s.vy,s.vx));ctx.scale(admin.projectileSize,admin.projectileSize);for(let j=3;j>0;j--){ctx.save();ctx.translate(-j*6,0);ctx.globalAlpha=.12*(4-j);drawHand(ctx,s.color);ctx.restore()}drawHand(ctx,s.color);ctx.restore()}
function drawPremiumProjectile(s){const a=Math.atan2(s.vy,s.vx),x=Math.round(s.x-camera.x),y=Math.round(s.y-camera.y);ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.scale(admin.projectileSize,admin.projectileSize);if(s.kind==='bow'){ctx.fillStyle='#6e584f';ctx.fillRect(-9,-1,22,3);ctx.fillStyle='#c8ac83';ctx.fillRect(-8,-1,21,1);sprite(ctx,['..c..','.chc.','chhhc','.chc.','..c..'],{c:s.color,h:'#eff5d8'},10,-2);ctx.fillStyle=s.color;ctx.fillRect(-8,-4,3,3);ctx.fillRect(-8,2,3,3)}else if(s.kind==='spear'){ctx.fillStyle='#b5a078';ctx.fillRect(-17,-1,32,2);sprite(ctx,['...h...','..hch..','.hccch.','hccccch','.hccch.','..hch..','...h...'],{h:'#d7eae7',c:s.color},10,-3)}else{ctx.globalAlpha=.3;ctx.fillStyle=s.color;ctx.fillRect(-12,-2,13,5);ctx.globalAlpha=1;sprite(ctx,['..cc..','.chhc.','chhhhc','chhhhc','.chhc.','..cc..'],{c:s.color,h:'#f4efd1'},-3,-3);ctx.fillStyle=s.color;ctx.fillRect(-7,-6,2,2);ctx.fillRect(-7,5,2,2)}ctx.restore()}

function pixelLine(c,x1,y1,x2,y2,color,width=1){const steps=Math.ceil(Math.max(Math.abs(x2-x1),Math.abs(y2-y1)));c.fillStyle=color;for(let i=0;i<=steps;i++){const t=steps?i/steps:0;c.fillRect(Math.round(x1+(x2-x1)*t),Math.round(y1+(y2-y1)*t),width,width)}}
function pixelPolygon(c,points,color){const low=Math.floor(Math.min(...points.map(v=>v[1]))),high=Math.ceil(Math.max(...points.map(v=>v[1])));c.fillStyle=color;for(let y=low;y<=high;y++){let hits=[];for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];if((a[1]<=y&&b[1]>y)||(b[1]<=y&&a[1]>y))hits.push(a[0]+(y-a[1])*(b[0]-a[0])/(b[1]-a[1]))}hits.sort((a,b)=>a-b);for(let i=0;i<hits.length-1;i+=2)c.fillRect(Math.ceil(hits[i]),y,Math.floor(hits[i+1])-Math.ceil(hits[i])+1,1)}}
function dragonWing(c,clock){c.save();c.translate(-3,-9);c.rotate(Math.sin(clock*9)*.22);c.scale(1,.65+Math.sin(clock*9)*.25);const points=[[0,0],[-5,-18],[-12,-34],[-19,-32],[-38,-17],[-28,-18],[-28,-6],[-19,-12],[-12,1],[-7,-6]];pixelPolygon(c,points,'#ae6564');for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];pixelLine(c,...a,...b,'#513845',1)}for(const tip of [[-12,-34],[-38,-17],[-28,-6],[-12,1]])pixelLine(c,0,0,...tip,'#e5b286',1);pixelLine(c,-12,-34,-19,-32,'#f4d09d',2);c.restore()}
function drawStyleEffects(){for(const e of styleEffects){const t=1-e.life/e.maxLife,x=Math.round(e.x-camera.x),y=Math.round(e.y-camera.y),r=Math.max(6,e.radius*t);ctx.save();ctx.globalAlpha=Math.min(1,e.life*3);if(e.kind==='shadowTransform'){drawShadowTransform(e,x,y,t);ctx.restore();continue}if(e.kind==='meleeStyle'){drawStyleMelee(e,x,y,t);ctx.restore();continue}if(drawAdminEffect(e,x,y,t)){ctx.restore();continue}if(e.kind==='lightning'){let prev=[x,y];for(let j=1;j<=8;j++){const f=j/8,next=[Math.round(x+(e.toX-e.x)*f+(j===8?0:j%2?9:-9)),Math.round(y+(e.toY-e.y)*f)];pixelLine(ctx,...prev,...next,e.color,3);pixelLine(ctx,...prev,...next,'#fff7ce',1);prev=next}}
else if(e.kind==='shadow'){for(let j=0;j<8;j++){ctx.save();ctx.globalAlpha=(1-t)*.3;ctx.translate(e.fromX-camera.x+(e.x-e.fromX)*j/8,y);drawHand(ctx,e.color,'fist');ctx.restore()}for(let j=0;j<10;j++){const a=j*Math.PI/5+t*3;ctx.fillStyle=e.color;ctx.fillRect(Math.round(x+Math.cos(a)*r),Math.round(y+Math.sin(a)*r),3,3)}}
else{const flame=e.color===styleDefs.flameFists.color;for(let j=0;j<16;j++){const a=j*Math.PI/8+t*(flame?1:-1),px=Math.round(x+Math.cos(a)*r),py=Math.round(y+Math.sin(a)*r);ctx.save();ctx.translate(px,py);ctx.rotate(a);if(e.kind==='earth'){sprite(ctx,['...oo....','..ohho...','.ohccco..','ohccccco.','occcccco.','.oooooo..'],{o:'#57464c',h:'#efd2a0',c:e.color},-4,-4,1.8)}else if(e.kind==='frost'){sprite(ctx,['...h...','c..h..c','.chhc..','hhhhhhh','.chhc..','c..h..c','...h...'],{c:e.color,h:'#e6faff'},-3,-3,1.4)}else if(flame){sprite(ctx,['...h....','..hhh...','.chhhc..','cchhhcc.','ccchccc.','.ccccc..','..ccc...'],{c:e.color,h:'#ffe2a3'},-3,-5,1.6)}else{sprite(ctx,['....hh...','..hhcc...','.hcccc...','hcccc....','hccc.....','.hh......'],{h:'#d9f9f5',c:e.color},-4,-4,1.6)}ctx.restore()}}ctx.restore()}
if(styleGuardUntil>time){ctx.save();ctx.translate(Math.round(p.x+p.w/2-camera.x),Math.round(p.y+p.h/2-camera.y));for(let j=0;j<6;j++){const a=time*1.5+j*Math.PI/3;ctx.save();ctx.translate(Math.round(Math.cos(a)*27),Math.round(Math.sin(a)*27));sprite(ctx,['.hhh.','hccch','hccch','.hhh.'],{h:'#ead1a1',c:'#968579'},-2,-2);ctx.restore()}ctx.restore()}}
function drawAdminEffect(e,x,y,t){if(!['cosmic','meteor','starfallFinale'].includes(e.kind))return false;const clock=animationClock();if(e.kind==='cosmic'){const radius=Math.max(20,e.radius*t);for(let j=0;j<24;j++){const a=j*Math.PI/12+t*2;ctx.save();ctx.translate(Math.round(x+Math.cos(a)*radius),Math.round(y+Math.sin(a)*radius));ctx.rotate(a);sprite(ctx,['..h..','.hch.','hccch','.hch.','..h..'],{h:'#f5e2ba',c:j%2?'#ccb0ef':'#afe8f3'},-2,-2,2);ctx.restore()}for(let j=0;j<4;j++){const a=j*Math.PI/2+clock;ctx.save();ctx.translate(x+Math.cos(a)*Math.min(radius,65),y+Math.sin(a)*Math.min(radius,65));ctx.rotate(a);ctx.scale(2.5,2.5);drawHand(ctx,j%2?'#c9acee':'#ace3f4','fist',true);ctx.restore()}}else{drawStarfallImpact(e,x,y,t)}return true}

// Fixed-length, overlapping limbs. Only locomotion changes the pose.
function creatureStep(speed,clock){return Math.abs(speed)>8?[0,1,2,1,0,-1,-2,-1][Math.floor(clock*8)%8]:0}
function drawHareLegs(c,step=0,airborne=false){const rows=['..oo......','..obbo....','..obbbo...','...obbo...','...obbo...','..obbbboo.','.ohhhhbbbo','oooooooooo'];sprite(c,rows,{o:'#463c42',b:'#aa8972',h:'#e4c9a4'},-14+step,-11+(airborne?-1:0));sprite(c,['.oo..','.obbo','.obbo','.obbo','.obbo','obbbbo','ohhhho','oooooo'],{o:'#463c42',b:'#ba9a7f',h:'#ead2af'},-step,-10+(airborne?-2:0));pixelOval(c,-14,-15,10,9,'#aa8972')}
function drawDrakeLegs(c,step=0,airborne=false){const rows=['.ooo...','ohcco..','occco..','occco..','.occo..','.occo..','.occco.','occhhco','ooooooo'];for(let i=0;i<2;i++){sprite(c,rows,{o:'#4e3540',c:i?'#a36650':'#835146',h:'#f0d29a'},(i?-1:-15)+(i?-step:step),-11+(airborne?-1:0));}}

function drawStarfallImpact(e,x,y,t){const finale=e.kind==='starfallFinale',impact=finale?.28:.3,fall=Math.min(1,t/impact),power=e.power||1,tilt=e.tilt||0;ctx.save();if(fall<1){const headY=y-340*(1-fall),headX=x+Math.sin(tilt)*240*(1-fall);for(let j=5;j>0;j--){ctx.save();ctx.globalAlpha*=.65-j*.1;ctx.translate(headX+Math.sin(tilt)*j*22,headY-j*24);ctx.rotate(Math.PI/2+tilt);ctx.scale((finale?4.5:2.5)*power,(finale?4.5:2.5)*power);drawHand(ctx,j%2?'#caa6ff':'#aff1ff','fist',true);ctx.restore()}ctx.save();ctx.translate(headX,headY);ctx.rotate(Math.PI/2+tilt);ctx.scale((finale?5.5:3)*power,(finale?5.5:3)*power);drawHand(ctx,e.color,'fist',true);ctx.restore();for(let j=0;j<6;j++){const dx=Math.round(Math.sin(j*2+t*19)*20);pixelLine(ctx,headX+dx,headY-55-j*20,headX+dx+2,headY-68-j*20,j%2?'#ffcaa9':'#eee2ff',2)}}else{const burstT=(t-impact)/(1-impact),radius=(finale?190:110)*burstT,fade=1-burstT;ctx.globalAlpha*=fade;for(let ring=0;ring<2;ring++){for(let j=0;j<32;j++){const a=j*Math.PI/16,r=radius*(1-ring*.25);ctx.fillStyle=ring?'#fff0d0':e.color;ctx.fillRect(Math.round(x+Math.cos(a)*r),Math.round(y+Math.sin(a)*r*.42),6,3)}}for(let j=0;j<14;j++){const a=j*Math.PI/7,dist=20+radius*.8,px=Math.round(x+Math.cos(a)*dist),py=Math.round(y+Math.sin(a)*dist-35*Math.sin(burstT*Math.PI));ctx.fillStyle=j%2?'#bb8de8':'#b6eaff';ctx.fillRect(px,py,3+j%3,3+j%3);if(j%2===0)pixelLine(ctx,x,y,px,py,e.color,1)}if(burstT<.4){ctx.save();ctx.translate(x,y);ctx.rotate(Math.PI/2);ctx.scale((finale?5.5:3)*power,(finale?5.5:3)*power);drawHand(ctx,e.color,'fist',true);ctx.restore();const length=(finale?95:55)*(1-burstT);for(let j=0;j<8;j++){const a=j*Math.PI/4;pixelLine(ctx,x+Math.cos(a)*15,y+Math.sin(a)*15,x+Math.cos(a)*length,y+Math.sin(a)*length,'#fff0ca',3)}}if(finale){for(let side of [-1,1]){const points=[[x,y+18],[x+side*35,y+11],[x+side*62,y+24],[x+side*96,y+15],[x+side*140*burstT,y+28]];for(let j=1;j<points.length;j++)pixelLine(ctx,...points[j-1],...points[j],'#f4e2ff',2)}}}ctx.restore()}
function starfallShake(){if(paused||!started||bossIntro)return 0;let strength=0;for(const e of styleEffects){if(!['meteor','starfallFinale'].includes(e.kind))continue;const age=e.maxLife-e.life,impact=e.maxLife*(e.kind==='starfallFinale'?.28:.3),since=age-impact;if(since>=0&&since<.18)strength=Math.max(strength,(e.kind==='starfallFinale'?7:3)*(1-since/.18))}return strength}

function drawSpellHand(c,color,form='palm'){if(form!=='sign'){drawHand(c,color,form);return}sprite(c,['....oo.oo.....','....oh.oh.....','....oh.oh.....','....oh.oh.....','....ohhho.....','..ooohhho.....','.ohhhcccco....','.ohcccccco....','..occccco.....','...occo.......','...oggo.......','...oooo.......'],{o:'#26364a',h:'#f4d2ad',c:color,g:'#7393aa'},-5,-9)}
function spellPixels(c,id,x,y,s=1,frame=0){c.save();c.translate(Math.round(x),Math.round(y));c.scale(s,s);const tick=Math.floor(frame*12)%3;if(id==='flameFists'){sprite(c,['........h.........','......hhhc........','....chhhhhc.......','..cchhhwhhhc......','.cchhhwwwhhhcc....','ccchhwwwwwhhccc...','ccchhhwww hhccc...','.cchhhhhhhhcc.....','..ccchhhhhcc......','....ccccc.........'],{c:'#e9734f',h:tick===1?'#ffcf78':'#ffb56d',w:'#fff2c0'},-8,-5);c.fillStyle='#ffe4a0';c.fillRect(-12-tick*2,-3,3,2);c.fillRect(-10-tick*2,3,2,2)}
else if(id==='waterFists'){sprite(c,['.......hhhh.......','.....hhcccch......','....hccccccch.....','...hcccchhccch....','..hcccch..hccch...','.hcccch....hhch...','hcccch......hhh...','hcccch............','.hcccch...........','..hhhhhh..........'],{c:'#569fc6',h:'#b4f4f4'},-8,-5);sprite(c,['..h..','.hch.','hccch','.hch.','..h..'],{c:'#65c6e0',h:'#c5fbef'},-13-tick,-4);c.fillStyle='#d7fdf4';c.fillRect(-12,5,2,2)}
else if(id==='frostFists'){sprite(c,['.......h.......','......hch......','....hhccchh....','..hhccchccc hh..','hhcccchhhcccchh','..hhccchccchh..','....hhccchh....','......hch......','.......h.......'],{c:'#72b6d7',h:'#e5fbff'},-7,-4)}
else if(id==='stoneFists'){sprite(c,['...oooooo....','..ohhhhcco...','.ohccccccco..','ohcccoccccco.','occcoccc cco.','occcccccccco.','.occccoccco..','..ooooooo....'],{o:'#61535e',c:'#b39975',h:'#e8c997'},-6,-4);c.fillStyle='#c5a47e';c.fillRect(-12,2,3,3);c.fillRect(-14,-3,2,2)}
else if(id==='thunderFists'){pixelPolygon(c,[[0,-9],[-8,1],[-2,1],[-6,9],[9,-2],[3,-2],[8,-9]],'#f6dc77');pixelLine(c,4,-7,-3,2,'#fff9d9',2);pixelLine(c,-10,tick-3,-19,tick+3,'#e0edac',2)}
else if(id==='shadowFists'){sprite(c,['......cchh.......','....cchhh........','...cchhh.........','..cchh...........','.cchh............','cchh.............','cchh.............','.cchh............','..cchh...........','...cchhhh........','....ccchhh.......','......cccchh.....'],{c:'#685592',h:'#c0a0e9'},-6,-6);c.globalAlpha=.35;pixelLine(c,-9,-3,-18,-5,'#b59ce0',3);pixelLine(c,-9,3,-18,6,'#b59ce0',3)}c.restore()}
function drawCastingStyle(c,id,active,t,aim,shirt){if(id==='shadowFists'){drawShadowClawStance(c,active,t,aim,shirt);return}if(!active||p.attackDuration!==.32){drawMeleeStyleHands(c,id,active,t,aim,shirt);return}const skin=avatar.skin,spellCast=p.attackDuration===.32,windup=active&&t<(spellCast?.35:.15),release=active&&t>=.35&&t<.85,clock=animationClock(),signStyle=['waterFists','thunderFists','shadowFists'].includes(id);let hands;
if(!active)hands=[{x:-7,y:1,a:-.3},{x:10,y:0,a:.15}];else if(windup)hands=[{x:4,y:-7,a:.5},{x:10,y:-7,a:-.5}];else if(id==='waterFists')hands=[{x:1,y:-4,a:-.7},{x:18,y:-5,a:aim}];else if(id==='flameFists')hands=[{x:12,y:3,a:aim+.15},{x:20,y:-3,a:aim-.1}];else if(id==='stoneFists')hands=[{x:-7,y:1,a:-.5},{x:18,y:5,a:aim+.4}];else hands=[{x:-3,y:-4,a:-.4},{x:20,y:-5,a:aim}];
for(let i=0;i<2;i++){const h=hands[i];if(active&&!windup&&(i===1||id==='flameFists')){const dx=h.x-4,dy=h.y+2;h.x=4+Math.cos(aim)*dx-Math.sin(aim)*dy;h.y=-2+Math.sin(aim)*dx+Math.cos(aim)*dy}if(active&&t>.85){const recovery=(t-.85)/.15;h.x=h.x*(1-recovery)+(i?10:-7)*recovery;h.y=h.y*(1-recovery)+(i?0:1)*recovery;h.a*=1-recovery}drawLimb(c,i?4:-3,-2,(h.x+(i?4:-3))/2,h.y+2,3,shirt);drawLimb(c,(h.x+(i?4:-3))/2,h.y+2,h.x,h.y,2,skin);c.save();c.translate(h.x,h.y);c.rotate(h.a);c.scale(.58*admin.weaponSize,.58*admin.weaponSize);drawSpellHand(c,skin,windup&&signStyle?'sign':id==='stoneFists'?'fist':id==='shadowFists'?'sign':release||id==='waterFists'||id==='frostFists'?'palm':'fist');c.restore()}
if(windup){c.save();c.translate(9,-8);const color=styleDefs[id].color;for(let j=0;j<8;j++){const a=j*Math.PI/4+clock*2;c.fillStyle=color;c.fillRect(Math.round(Math.cos(a)*12),Math.round(Math.sin(a)*12),2,2)}c.restore()}
if(release&&spellCast){c.save();c.translate(hands[1].x+7,hands[1].y);c.rotate(aim);spellPixels(c,id,id==='flameFists'?10:8,0,id==='flameFists'?1.3:.8,clock);c.restore()}
if(!active){const mote=Math.round(Math.sin(clock*3)*2);c.save();c.globalAlpha=.7;spellPixels(c,id,13,-10+mote,.38,clock);c.restore()}}

function drawElementalProjectile(s){ctx.save();ctx.translate(Math.round(s.x-camera.x),Math.round(s.y-camera.y));ctx.rotate(Math.atan2(s.vy,s.vx));ctx.scale(admin.projectileSize,admin.projectileSize);for(let j=2;j>0;j--){ctx.save();ctx.globalAlpha=.16/j;spellPixels(ctx,s.styleId,-j*9,0,.8,s.age||0);ctx.restore()}spellPixels(ctx,s.styleId,0,0,1,s.age||0);ctx.restore()}
const styleReach={waterFists:102,flameFists:112,frostFists:98,stoneFists:92,thunderFists:106,shadowFists:108};
function styleMeleeStrike(id,angle){const empowered=id==='shadowFists'&&shadowFormActive(),reach=styleReach[id]*(empowered?1.35:1),d=styleDefs[id],x=p.x+p.w/2,y=p.y+p.h/2;styleEffects.push({kind:'meleeStyle',id,empowered,color:d.color,x,y,angle,alternate:p.swingIndex%2,radius:reach,life:d.cooldown,maxLife:d.cooldown});for(const e of styleTargets(reach)){const tx=Math.max(e.x,Math.min(x,e.x+e.w)),ty=Math.max(e.y,Math.min(y,e.y+e.h)),dx=tx-x,dy=ty-y,dist=Math.hypot(dx,dy);if(dist>20&&(dx*Math.cos(angle)+dy*Math.sin(angle))/dist<.25)continue;let blocked=false;for(let step=8;step<dist;step+=8){const f=step/dist;if(solid(Math.floor((x+dx*f)/T),Math.floor((y+dy*f)/T))){blocked=true;break}}if(!blocked)styleEnemyHit(e,d.damage*(empowered?1.6:1))}}
function drawStyleMelee(e,x,y,t){drawPhysicalMelee(e,x,y,t)}

function waterStyleSurface(){if(weapon!=='waterFists'||mount>=0||keys.s||keys.arrowdown)return false;const bottom=p.y+p.h,tx=Math.floor((p.x+p.w/2)/T),ty=Math.round(bottom/T);return Math.abs(bottom-ty*T)<1.5&&get(tx,ty)===8&&get(tx,ty-1)!==8}
function waterStyleCollision(o,previousBottom){if(o!==p||weapon!=='waterFists'||mount>=0||keys.s||keys.arrowdown)return false;const y=Math.floor((o.y+o.h-.001)/T);for(let x=Math.floor(o.x/T);x<=Math.floor((o.x+o.w-.001)/T);x++)if(get(x,y)===8&&get(x,y-1)!==8&&previousBottom<=y*T+.001&&o.y+o.h>=y*T)return true;return false}
function drawStyleAura(c,id,x,y){if(!styleDefs[id]||p.hp<=0)return;const clock=animationClock(),moving=Math.abs(p.vx)>20;c.save();c.translate(Math.round(x),Math.round(y));c.scale(p.face,1);
if(id==='shadowFists'){drawShadowAura(c,clock)}
else if(id==='waterFists'){for(let j=0;j<16;j++){const a=clock*1.1+j*Math.PI/8,px=Math.round(Math.cos(a)*21),py=Math.round(9+Math.sin(a)*7);c.fillStyle=j%3?'#68bdcfaa':'#d4fff0';c.fillRect(px,py,4,2);if(j%4===0)c.fillRect(px,py-3,2,3)}for(let j=0;j<4;j++){const rise=(clock*9+j*8)%32;c.fillStyle='#93e4e899';c.fillRect(-15+j*9,-rise,2,3)}if(waterStyleSurface()){c.fillStyle='#3e8bac';c.fillRect(-13,16,29,3);c.fillStyle='#bcf6ed';c.fillRect(-14,15,30,1);c.fillRect(15,13,3,3);if(moving)for(let j=0;j<5;j++){c.fillStyle=j%2?'#bcf6ed':'#65bcd5';c.fillRect(-19-j*5,16+(j%2),4,2);c.fillRect(-18-j*5,10-j%3,2,2)}}}
else if(id==='flameFists'){c.save();c.translate(-16,-12);c.globalAlpha=[.25,.34,.48,.6,.42,.28][Math.floor(clock*4)%6];c.scale(1.4,1.4);drawDragon(c,clock,false,0,true);c.restore();for(let j=0;j<8;j++){const rise=(clock*17+j*7)%43,px=Math.round(Math.sin(j*2+clock)*13);c.fillStyle=j%2?'#ffb27799':'#ffe09fbb';c.fillRect(px-8,-rise+13,2,3)}}
else if(id==='frostFists'){for(let j=0;j<6;j++){const a=clock*.6+j*Math.PI/3;spellPixels(c,id,Math.cos(a)*22,-5+Math.sin(a)*24,.3,clock)}c.fillStyle='#a6e4ed88';c.fillRect(-12,16,25,2)}
else if(id==='stoneFists'){for(let j=0;j<4;j++){const a=clock*.7+j*Math.PI/2;spellPixels(c,id,Math.cos(a)*23,7+Math.sin(a)*10,.45,clock)}c.fillStyle='#d6b67b99';c.fillRect(-10,17,22,2)}
else if(id==='thunderFists'){for(let j=0;j<3;j++){const side=j%2?-1:1,yy=-18+j*12+(Math.floor(clock*9)%3);pixelLine(c,side*14,yy,side*19,yy+5,'#f7e99c99',1);pixelLine(c,side*19,yy+5,side*15,yy+10,'#fff7c7',1)}}
else if(id==='omniFists'){for(let j=0;j<6;j++){const a=clock+j*Math.PI/3;c.fillStyle=j%2?'#dbc0f4':'#b5ecf3';c.fillRect(Math.round(Math.cos(a)*28),Math.round(-5+Math.sin(a)*28),2,2)}}c.restore()}

let shadowFormTime=0,shadowTransformCooldown=0;
function shadowFormActive(){return weapon==='shadowFists'&&shadowFormTime>0&&p.hp>0}
function useShadowTransformation(){if(adminReckoning)return false;if(!started||paused||bossIntro||p.hp<=0||weapon!=='shadowFists'||!owned.has('shadowFists'))return false;if(shadowTransformCooldown>0){notify('Eclipse Form recharging · '+Math.ceil(shadowTransformCooldown)+'s');return false}shadowFormTime=10;shadowTransformCooldown=30;mount=-1;styleEffect('shadowTransform','#cfafff',100,1);burst(p.x+p.w/2,p.y+12,'#b796ef',22);beep(340);updateStyleHud();notify('Eclipse Form · 10s · stronger claws, longer reach, +20% speed and +6 defense');return true}
function tickShadowForm(dt){shadowTransformCooldown=Math.max(0,shadowTransformCooldown-dt);if(weapon!=='shadowFists'||p.hp<=0){shadowFormTime=0;return}shadowFormTime=Math.max(0,shadowFormTime-dt)}
function handleStyleRAbility(){if(weapon==='lineOfCode')return useCodeAbility('input');if(weapon==='shadowFists')return useShadowTransformation();return useAdminRAbility()}
function drawShadowDragon(c,clock,empowered=false){c.save();const scale=empowered?1.25:.95;c.scale(scale,scale);const bob=Math.round(Math.sin(clock*2)*2),wing=Math.round(Math.sin(clock*3)*5);c.translate(-6,-10+bob);c.globalAlpha=empowered?.68:.45;
for(const side of [-1,1]){c.save();c.scale(side,1);const points=[[-6,-14],[-15,-37-wing],[-23,-60-wing],[-43,-49],[-62,-23],[-46,-29],[-43,-12],[-29,-22],[-23,-4],[-14,-15]];pixelPolygon(c,points,'#32284b');for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];pixelLine(c,...a,...b,'#9471bd',1)}for(const tip of [[-23,-60-wing],[-62,-23],[-43,-12],[-23,-4]])pixelLine(c,-6,-14,...tip,'#69508f',1);c.restore()}
for(let j=9;j>=0;j--){const px=Math.round(-26+Math.sin(j*.6+clock*.5)*10),py=22-j*6;pixelOval(c,px-6,py-4,12,11,'#221e38');pixelOval(c,px-4,py-3,8,8,'#544173');c.fillStyle='#a081c6';c.fillRect(px-5,py-5,3,3)}
c.globalAlpha=empowered?.95:.8;pixelPolygon(c,[[-24,-27],[-23,-38],[-17,-47],[-8,-44],[-13,-32],[-9,-18]],'#544173');pixelLine(c,-23,-34,-17,-45,'#a385c8',2);sprite(c,['.....h........h..........','....hch......hch.........','....hccoo..oocch.........','.....occcoo ccco.........','....occcccccccc o........','...occhccccccccccoo......','..occccehhcccehhccco.....','..occcceeeccceeec cco....','...occccccccccccccchhho..','....occcccccccccchhhhho..','.....occcooooooooccco....','......ocohhhhhhhhco......','.......occcccc cco.......','........oooooooo........'],{o:'#201c32',c:'#5c467e',h:'#b999dd',e:empowered?'#bbf7f3':'#d4c4ff'},-25,-58,1.25);c.fillStyle='#e4d4ff';c.fillRect(-4,-44,3,2);c.fillRect(-15,-44,2,2);c.restore()}
function drawShadowClaw(c,empowered=false){sprite(c,['..oooooo.....','.ohhhhcco....','ohccccccco...','occcgccccco..','occcgccccco..','.occccccco...','..occccco....','...oggo......','...oooo......'],{o:'#211c35',c:empowered?'#735297':'#503964',h:'#ab8ed0',g:'#d9c0fa'},-5,-4);for(let j=0;j<3;j++){const y=-4+j*4,len=(empowered?19:14)-Math.abs(j-1)*2;pixelPolygon(c,[[2,y],[len-2,y-2],[len+3,y+1],[len-1,y+2],[4,y+2]],'#352b50');pixelLine(c,4,y,len-2,y-2,'#c7a9eb',1);pixelLine(c,len-2,y-2,len+3,y+1,empowered?'#e8daff':'#b99bdc',1)}}
function drawShadowClawStance(c,active,t,aim,shirt){const empowered=shadowFormActive(),stroke=active?meleeMotion(t).strike:0,sign=p.swingIndex%2?1:-1;for(let hand=0;hand<2;hand++){const striking=active&&(hand===p.swingIndex%2||empowered),angle=striking?aim+sign*(-.8+stroke*1.5):hand?-.2:-.6,length=striking?12+stroke*20:hand?13:8,x=Math.round(Math.cos(angle)*length+(hand?3:-6)),y=Math.round(Math.sin(angle)*length+(hand?-1:3));drawLimb(c,hand?4:-4,-2,(x+(hand?4:-4))/2,y+7,3,shirt);drawLimb(c,(x+(hand?4:-4))/2,y+7,x,y,2,empowered?'#70518e':avatar.skin);c.save();c.translate(x,y);c.rotate(angle);c.scale((empowered?.85:.7)*admin.weaponSize,(empowered?.85:.7)*admin.weaponSize);drawShadowClaw(c,empowered);c.restore()}}
function drawShadowClawSlash(c,e,x,y,t){c.save();c.translate(x,y);c.rotate(e.angle);c.scale(admin.projectileSize,admin.projectileSize);const r=e.radius*(.55+Math.sin(t*Math.PI)*.25),sweep=(e.alternate?1:-1)*(-.85+t*1.65);c.globalAlpha=Math.max(0,1-t);for(let claw=0;claw<3;claw++){const radius=r-claw*9;let previous=null;for(let j=0;j<18;j++){const a=sweep-.75+j*.055,px=Math.round(Math.cos(a)*radius),py=Math.round(Math.sin(a)*radius);if(previous){pixelLine(c,...previous,px,py,claw%2?'#9d72c7':'#d0b2f5',3);pixelLine(c,previous[0]+1,previous[1],px+1,py,e.empowered?'#efe1ff':'#e0cafb',1)}previous=[px,py]}if(e.empowered){c.fillStyle='#d5b5fa';c.fillRect(previous[0]+4,previous[1]-1,3,3)}}c.restore()}
function drawShadowAura(c,clock){const empowered=shadowFormActive();drawShadowDragon(c,clock,empowered);for(let j=0;j<(empowered?18:12);j++){const a=clock*(empowered?1.8:1.2)+j*Math.PI/6,px=Math.round(Math.cos(a)*(empowered?29:22)),py=Math.round(-4+Math.sin(a)*26);c.save();c.globalAlpha=.18+(j%3)*.1;pixelOval(c,px-6,py-3,12,7,'#60417e');c.fillStyle='#b797dd';c.fillRect(px-3,py-1,5,1);c.restore()}for(let j=0;j<8;j++){const rise=(clock*17+j*7)%54;c.fillStyle=j%2?'#a77cd099':'#5d427b88';c.fillRect(-19+(j*11)%37,16-rise,2,3)}if(empowered){c.fillStyle='#c09cdd88';c.fillRect(-17,16,35,2);for(let j=0;j<8;j++){const a=clock+j*Math.PI/4;c.fillStyle='#d9c3ef';c.fillRect(Math.round(Math.cos(a)*32),Math.round(Math.sin(a)*10+14),3,2)}}}
function drawShadowTransform(e,x,y,t){const c=ctx;c.save();c.translate(x,y);for(let j=0;j<24;j++){const a=j*Math.PI/12+t*2,r=e.radius*t;c.fillStyle=j%3?'#a986ce':'#d1b8ef';c.fillRect(Math.round(Math.cos(a)*r),Math.round(Math.sin(a)*r*.65),3,4)}for(let j=0;j<8;j++){const xx=-28+j*8,height=Math.sin(t*Math.PI)*70;c.fillStyle='#6c4d9477';c.fillRect(xx,18-height,4,height)}c.restore()}

function meleeMotion(t){t=Math.max(0,Math.min(1,t));if(t<.22)return{load:t/.22,strike:0,release:0};if(t<.55){const u=(t-.22)/.33;return{load:1,strike:1-Math.pow(1-u,3),release:0}}const u=(t-.55)/.45;return{load:1,strike:1-u*u,release:u}}
