function nearSkyLift(){return started&&p.hp>0&&Math.hypot(p.x+p.w/2-skyLift.x,p.y+p.h-skyLift.y)<110}
function interactSky(){if(paused||boss||bossIntro||p.hp<=0)return false;if(nearSkyAdmin())return talkSkyAdmin();if(nearSkyLift())return travelSky(true);return talkSkyAdmin()}
function travelSky(up){if(adminReckoning||!started||boss||bossIntro||p.hp<=0)return false;if(up&&!nearSkyLift()&&!adminUnlocked)return false;if(!up&&(!nearSkyAdmin()||$('sky-npc-panel').classList.contains('hidden')))return false;closePanels();p.x=up?skyAdmin.x-65:skyLift.x-15;p.y=(up?skyAdmin.y:skyLift.y)-p.h-2;p.vx=p.vy=0;p.attack=0;mouse.held=false;dashTime=0;p.inv=3;shots.length=0;resetNaturalEncounter();if(activePet){activePet.x=p.x-25;activePet.y=p.y}updateSkyHud();notify(up?'Welcome to the Admin island! Walk to the NPC and press I.':'Returned to the Astral Sky Lift');return true}
function drawSkyLift(){const x=skyLift.x-camera.x,y=skyLift.y-camera.y;if(x< -80||x>vw+80||y< -100||y>vh+100)return;ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.fillStyle='#312746';ctx.fillRect(-24,-4,48,4);ctx.fillStyle='#ada0d8';ctx.fillRect(-24,-5,48,2);ctx.fillRect(-22,-64,5,59);ctx.fillRect(17,-64,5,59);ctx.fillRect(-22,-65,44,5);ctx.fillStyle='#bd74fa';ctx.globalAlpha=.24;ctx.fillRect(-16,-59,32,54);ctx.globalAlpha=1;for(let j=0;j<8;j++){ctx.fillStyle=j%2?'#debbff':'#946ee0';ctx.fillRect(-13+j%3*11,-9-(j*8+time*14)%47,3,3)}ctx.textAlign='center';ctx.font='bold 12px monospace';ctx.fillStyle='#f0d5ff';ctx.fillText('ASTRAL SKY LIFT',0,-84);ctx.font='11px monospace';ctx.fillText(nearSkyLift()?'[ I ] Visit the Admin':'Admin island ↑',0,-70);ctx.restore()}
