function nearSkyAdmin(){return !skyAdmin.vanished&&started&&p.hp>0&&Math.hypot(p.x+p.w/2-skyAdmin.x,p.y+p.h-skyAdmin.y)<100}
function talkSkyAdmin(){if(paused||bossIntro||!nearSkyAdmin()){if(started&&!paused)notify('Find the Admin on the island high above Astral · x 2610');return false}skyAdmin.avatar={...avatar};updateSkyDragonDialogue();$('sky-gift-result').textContent='Choose a gift. Each roll gives you a usable glitched weapon.';panel('sky-npc-panel');return true}
function claimSkyGift(){if(!paused||$('sky-npc-panel').classList.contains('hidden')||!nearSkyAdmin())return false;let pool=Object.keys(glitchDefs).filter(id=>!owned.has(id));if(!pool.length)pool=Object.keys(glitchDefs);const id=pool[Math.floor(rand()*pool.length)];owned.add(id);equipItem(id);if(adminRevenge.defeated){$('sky-gift-result').textContent='A peace offering: '+items[id].name+'. No trial this time.';beep(780);return id}$('sky-gift-result').textContent='Received '+items[id].name+'! Equipped. '+items[id].detail;if(!skyTrial){skyTrial={remaining:60,warned:false};notify('60-second weapon trial started. The Admin will return for a finale!')}$('sky-gift-result').textContent+=' · '+Math.ceil(skyTrial.remaining)+'s left until the Admin’s finale. Close this window to start playing.';beep(780);return id}
