function hitCodeMelee(swing){const x=p.x+p.w/2,y=p.y+p.h/2;for(const enemy of styleTargets(swing.radius)){if(swing.hits.has(enemy))continue;const tx=Math.max(enemy.x,Math.min(x,enemy.x+enemy.w)),ty=Math.max(enemy.y,Math.min(y,enemy.y+enemy.h)),dx=tx-x,dy=ty-y,d=Math.hypot(dx,dy);if(d>20&&(dx*Math.cos(swing.angle)+dy*Math.sin(swing.angle))/d<.2)continue;let wall=false;for(let n=8;n<d-3;n+=8)if(solid(Math.floor((x+dx*n/d)/T),Math.floor((y+dy*n/d)/T))){wall=true;break}if(!wall){swing.hits.add(enemy);codeHit(enemy,260,swing.boosted?1.5:1)}}}
