function codeStonePart(points,seed,boosted,theme=codeHandThemes[0],ink=ctx){ink.beginPath();points.forEach(([x,y],i)=>i?ink.lineTo(x,y):ink.moveTo(x,y));ink.closePath();ink.fillStyle=theme.base;ink.fill();ink.save();ink.clip();ink.fillStyle=theme.dark;ink.beginPath();ink.moveTo(points[0][0],points[0][1]);ink.lineTo(points[2][0],points[2][1]);ink.lineTo(points[3][0],points[3][1]);ink.lineTo(points[4][0],points[4][1]);ink.lineTo(points.at(-1)[0],points.at(-1)[1]);ink.fill();const xs=points.map(v=>v[0]),ys=points.map(v=>v[1]),left=Math.min(...xs),right=Math.max(...xs),top=Math.min(...ys),bottom=Math.max(...ys);for(let j=0;j<24;j++){const x=Math.floor((left+hash(seed+j*7,seed)*(right-left))/4)*4,y=Math.floor((top+hash(seed,seed+j*11)*(bottom-top))/4)*4;ink.fillStyle=j%3?theme.light:theme.dark;ink.fillRect(x,y,j%3===0?8:4,4)}ink.strokeStyle=theme.lava?theme.accent:theme.dark;ink.lineWidth=theme.lava?5:3;ink.beginPath();const mx=Math.round((left+right)/8)*4;ink.moveTo(mx-8,top+4);ink.lineTo(mx-8,top+(bottom-top)*.3);ink.lineTo(mx+4,top+(bottom-top)*.3);ink.lineTo(mx+4,top+(bottom-top)*.6);ink.lineTo(mx-4,top+(bottom-top)*.6);ink.lineTo(mx-4,bottom-4);ink.stroke();if(theme.lava){ink.strokeStyle='#ffe29a';ink.lineWidth=2;ink.stroke()}ink.restore();ink.beginPath();points.forEach(([x,y],i)=>i?ink.lineTo(x,y):ink.moveTo(x,y));ink.closePath();ink.strokeStyle=theme.edge;ink.lineWidth=4;ink.stroke();ink.beginPath();ink.moveTo(points[0][0]+2,points[0][1]+2);for(let i=1;i<Math.min(3,points.length);i++)ink.lineTo(points[i][0],points[i][1]+2);ink.strokeStyle=theme.light;ink.lineWidth=3;ink.stroke()}
