function drawPixelCodeHand(curl,boosted,theme,angle=0,impact=0){if(!codeHandPixelBuffer){codeHandPixelBuffer=typeof OffscreenCanvas==='function'?new OffscreenCanvas(192,192):document.createElement('canvas');codeHandPixelBuffer.width=codeHandPixelBuffer.height=192}const ink=codeHandPixelBuffer.getContext('2d');ink.clearRect(0,0,192,192);ink.save();ink.imageSmoothingEnabled=false;ink.translate(96,96);ink.rotate(angle);ink.scale(.3375*(1+impact*.1),.3375*(1-impact*.14));drawCodeHandAnatomy(curl,boosted,theme,ink);ink.restore();ctx.imageSmoothingEnabled=false;ctx.drawImage(codeHandPixelBuffer,-384,-384,768,768)}
