function drawCodeDomainSky(){const domain=codeWeapon.domain;if(!domain)return;const fade=Math.min(1,domain.age*2,(8-domain.age)*2);ctx.save();ctx.globalAlpha=fade;const g=ctx.createLinearGradient(0,0,0,vh);g.addColorStop(0,'#020615');g.addColorStop(1,domain.boosted?'#251338':'#071d28');ctx.fillStyle=g;ctx.fillRect(0,0,vw,vh);ctx.strokeStyle='#65d7cc33';ctx.lineWidth=1;for(let i=0;i<12;i++){const x=(i*131-camera.x*.12+vw*100)%vw;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(vw/2+(x-vw/2)*2,vh);ctx.stroke()}ctx.fillStyle='#baf5e6';ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText('OVERRUN · DOMAIN OF CODE',vw/2,90);ctx.restore()}
function drawCodeDomainVeil(){const d=codeWeapon.domain;if(!d)return;ctx.save();ctx.fillStyle='#04081899';ctx.globalAlpha=Math.min(1,d.age*2,(8-d.age)*2);ctx.fillRect(0,0,vw,vh);const x=d.x-camera.x,y=d.y-camera.y;ctx.strokeStyle=d.boosted?'#d0adff88':'#85e9d388';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y,d.radius,d.radius*.7,0,Math.PI,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.ellipse(x,y+25,d.radius,d.radius*.13,0,0,Math.PI*2);ctx.stroke();for(let j=0;j<12;j++){const a=j*Math.PI/6+time*.15;ctx.fillStyle='#b7f6e5';ctx.font='11px monospace';ctx.fillText(['<execute>','[override]','{delete}'][j%3],x+Math.cos(a)*d.radius*.8,y+Math.sin(a)*d.radius*.13)}ctx.restore()}

function drawCodeTool(c,id,clock){c.fillStyle='#273345';c.fillRect(-3,-1,5,12);c.fillStyle='#bb9469';c.fillRect(-1,0,2,10);c.fillStyle='#c6ece8';if(id===0){c.fillRect(-8,-5,16,5);c.fillRect(-9,-1,4,5);c.fillRect(5,-1,4,4)}else if(id===1){c.fillRect(-7,-7,14,9);c.fillStyle='#698a9c';c.fillRect(-5,-5,10,4)}else if(id===2){c.fillRect(-6,-8,12,6);c.fillRect(-6,-3,3,5);c.fillRect(3,-3,3,5);c.fillStyle='#162c3c';c.fillRect(-2,-8,4,4)}else if(id===3){c.fillStyle='#d79bdf';c.fillRect(-7,-5,14,8);c.fillStyle='#f0d0ef';c.fillRect(-7,-5,6,8)}else{c.fillStyle='#a4f3d7';for(let j=0;j<7;j++)c.fillRect(-5,-7+j,Math.max(1,9-j),1);c.fillStyle='#263a48';c.fillRect(-3,-3,2,9)}}
function drawCodeIcon(c,pose){c.save();c.translate(pose.x,pose.y);c.rotate(pose.angle);c.scale(admin.weaponSize,admin.weaponSize);c.strokeStyle='#a7ffdf';c.lineWidth=3;c.beginPath();c.moveTo(2,0);c.lineTo(33,0);c.lineTo(43,-5);c.stroke();c.strokeStyle='#e8fff5';c.lineWidth=1;c.beginPath();c.moveTo(4,-2);c.lineTo(34,-2);c.stroke();c.fillStyle='#547ca4';c.fillRect(4,-6,3,12);c.fillStyle='#e6c3ff';c.font='9px monospace';c.fillText('</>',14,-6);c.restore()}

function drawCodeOrbit(front){if(weapon!=='lineOfCode'||!owned.has('lineOfCode'))return;const x=p.x+p.w/2-camera.x,y=p.y+p.h/2-camera.y,boosted=codeInputActive(),clock=time*(boosted?1.8:1);ctx.save();for(let j=0;j<10;j++){const a=clock+j*Math.PI/5;if((Math.sin(a)>0)!==front)continue;const r=boosted?65:48,xx=x+Math.cos(a)*r,yy=y+Math.sin(a)*r*.6;ctx.save();ctx.translate(Math.round(xx),Math.round(yy));ctx.rotate(Math.sin(a)*.35);const scale=(.6+(.5+.5*Math.sin(clock*2+j))*.6)*admin.weaponSize;ctx.scale(scale,scale);if(j<4)drawCodeTool(ctx,j,clock);else if(j%3===0){ctx.strokeStyle='#b8fbe3';ctx.lineWidth=2;ctx.strokeRect(-9,-7,18,14);ctx.font='9px monospace';ctx.fillStyle='#d3b7ff';ctx.fillText('{ }',-8,3)}else if(j%3===1){ctx.strokeStyle='#b8d9ff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(8,-4);ctx.lineTo(8,5);ctx.lineTo(0,11);ctx.lineTo(-8,5);ctx.lineTo(-8,-4);ctx.closePath();ctx.stroke();ctx.beginPath();ctx.moveTo(-8,-4);ctx.lineTo(0,2);ctx.lineTo(8,-4);ctx.moveTo(0,2);ctx.lineTo(0,11);ctx.stroke()}else{ctx.fillStyle='#ddc4ff';ctx.fillRect(-2,-14,4,28);ctx.fillStyle='#fff4e0';ctx.fillRect(-5,7,10,2);ctx.fillStyle='#9ff4dc';ctx.fillRect(2,-14,2,21)}ctx.restore()}for(let j=0;j<4;j++){const a=-clock*.65+j*Math.PI/2;if((Math.sin(a)>0)!==front)continue;ctx.save();ctx.translate(x+Math.cos(a)*(boosted?100:79),y+Math.sin(a)*(boosted?51:38));ctx.rotate(Math.cos(a)*.22);ctx.globalAlpha=.85;ctx.font=boosted?'10px monospace':'9px monospace';ctx.textAlign='center';ctx.fillStyle=['#a1ffda','#aedaff','#d9b3ff','#fff0be'][j];ctx.fillText(['destroy(world);','input(flight);','overrun(domain);','creator.override();'][j],0,0);ctx.restore()}if(boosted&&!front){ctx.strokeStyle='#b4ffe655';ctx.lineWidth=2;for(let ring=0;ring<3;ring++){ctx.beginPath();ctx.ellipse(x,y+ring*8-8,45+ring*7,14+ring*2,time*.4,0,Math.PI*2);ctx.stroke()}for(let side of [-1,1])for(let j=0;j<5;j++){ctx.fillStyle=j%2?'#9bf1d77f':'#b9a0ed88';ctx.fillRect(x+side*(20+j*8),y-6-j*6+Math.sin(time*3+j)*3,side*13,3)}}ctx.restore()}

function drawCodeShot(s){const x=s.x-camera.x,y=s.y-camera.y;ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(s.vy,s.vx));ctx.fillStyle=s.enemy?'#ed90cd':'#a0f6d4';ctx.globalAlpha=.35;ctx.fillRect(-20,-3,24,5);ctx.globalAlpha=1;ctx.scale(.8,.8);drawCodeTool(ctx,s.tool||0,time);ctx.restore()}
function drawCodeEffects(){const x=p.x+p.w/2-camera.x,y=p.y+p.h/2-camera.y;if(codeInputActive()){ctx.save();ctx.strokeStyle='#b7fce577';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,38+Math.sin(time*3)*3,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#c9ffe9';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('INPUT · '+(codeInputFlightActive()?'FLIGHT · ':'')+'1.5× · '+Math.ceil(codeWeapon.inputUntil-time)+'s',x,y-70);for(let j=0;j<14;j++){const u=(time*.6+j/14)%1;ctx.globalAlpha=1-u;ctx.fillStyle=j%2?'#b9a0ff':'#94f3dc';ctx.fillRect(x+Math.sin(j*3+time)*33,y+28-u*85,2,5)}ctx.restore()}
const swing=codeWeapon.melee;if(swing){const t=Math.min(1,swing.age/.34),sign=swing.alternate?1:-1;ctx.save();ctx.translate(x,y);ctx.rotate(swing.angle);ctx.globalAlpha=Math.min(1,(1-t)*2);for(let layer=0;layer<4;layer++){ctx.strokeStyle=[swing.boosted?'#cca1ff':'#6ecdb5','#b3ffe1','#edfff7','#e6c6ff'][layer];ctx.lineWidth=[17,8,3,1][layer];ctx.beginPath();ctx.arc(0,0,swing.radius-layer*6,-1.28+sign*(t-.5)*.22,1.28+sign*(t-.5)*.22);ctx.stroke()}for(let j=0;j<8;j++){const a=-1.2+j*.34;ctx.fillStyle=j%2?'#beffe7':'#e1c2ff';ctx.font='10px monospace';ctx.fillText(j%2?'/':'01',Math.cos(a)*(swing.radius-15),Math.sin(a)*(swing.radius-15))}ctx.restore()}
const cast=codeWeapon.terrain;if(cast?.mode==='hand')drawCodeRockHand(cast);if(cast&&cast.mode!=='hand'){for(const chunk of cast.chunks){if(chunk.hit)continue;const pos=terrainChunkPosition(cast,chunk),xx=pos.x-camera.x,yy=pos.y-camera.y;ctx.save();ctx.translate(xx,yy);ctx.rotate(pos.angle);ctx.shadowColor=cast.boosted?'#c7a1ff':'#a3f0dd';ctx.shadowBlur=10;ctx.fillStyle='#7edbc344';ctx.fillRect(-42,-32,84,64);ctx.shadowBlur=0;for(const tile of chunk.tiles)tileDraw(ctx,tile.v,-40+tile.xx*20,-30+tile.yy*20,20,Math.floor(chunk.x/T)+tile.xx,Math.floor(chunk.y/T)+tile.yy);ctx.shadowBlur=0;ctx.strokeStyle='#c1ffe6';ctx.lineWidth=2;ctx.strokeRect(-42,-32,84,64);ctx.fillStyle='#deceff';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('world.chunk',0,-37);ctx.restore();if(cast.age<1.1){ctx.save();ctx.strokeStyle='#b1f2dc55';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(xx,yy);ctx.stroke();ctx.restore()}}}
for(const rain of codeWeapon.rain){const xx=rain.x-camera.x,yy=rain.y-camera.y;ctx.save();ctx.strokeStyle=rain.boosted?'#caa4ff66':'#96f4d766';ctx.lineWidth=rain.width*.6;ctx.beginPath();ctx.moveTo(xx,yy-125);ctx.lineTo(xx,yy+8);ctx.stroke();ctx.font=rain.boosted?'bold 12px monospace':'11px monospace';ctx.textAlign='center';for(let j=0;j<9;j++){ctx.globalAlpha=(1-j/10)*Math.min(1,rain.life*3);ctx.fillStyle=j===0?'#edfff4':rain.boosted?'#ccb0ff':'#a0f5d7';ctx.fillText(['01','{}','</>','exec','[]'][(j+rain.seed)%5],xx,yy-j*15)}ctx.restore()}
for(const e of codeWeapon.effects){const t=1-e.life/e.max,xx=e.x-camera.x,yy=e.y-camera.y;ctx.save();ctx.globalAlpha=1-t;if(e.kind==='hit'){for(let j=0;j<6;j++){const a=j*Math.PI/3;pixelLine(ctx,xx+Math.cos(a)*4,yy+Math.sin(a)*4,xx+Math.cos(a)*e.radius*t,yy+Math.sin(a)*e.radius*t,e.boosted?'#e1b4ff':'#baffdf',2)}ctx.font='9px monospace';ctx.fillStyle='#effff5';ctx.fillText(e.boosted?'CRITICAL();':'hit();',xx-20,yy-12-t*18)}else if(e.kind==='impact'){const material=e.handBiome===undefined?null:codeHandThemes[e.handBiome];ctx.strokeStyle=material?material.accent:e.boosted?'#dbb7ff':'#b6f7d3';ctx.lineWidth=4*(1-t)+1;ctx.beginPath();ctx.ellipse(xx,yy,10+t*e.radius,6+t*e.radius*.35,0,0,Math.PI*2);ctx.stroke();for(let j=0;j<12;j++){const a=j*Math.PI/6;pixelLine(ctx,xx,yy,xx+Math.cos(a)*t*e.radius*.7,yy+Math.sin(a)*t*e.radius*.35,material?material.debris:'#b0a29a',2)}ctx.fillStyle=material?material.light:'#e4fff2';ctx.fillRect(xx-3,yy-40*(1-t),6,40*(1-t));if(material?.lava){for(let j=0;j<12;j++){ctx.fillStyle=j%2?'#ffbf4c':'#e55a2c';ctx.fillRect(Math.round(xx+(j-5.5)*19*(.5+t)),Math.round(yy+Math.sin(j*2)*9),12,4)}}}else{ctx.strokeStyle=e.kind==='destroy'?'#d1b2ff':'#a6f3dc';ctx.lineWidth=3;ctx.beginPath();ctx.arc(xx,yy,10+t*e.radius,0,Math.PI*2);ctx.stroke();ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillStyle=ctx.strokeStyle;ctx.fillText(e.kind.toUpperCase()+'();',xx,yy-20-t*45)}ctx.restore()}}

function updateRevengeGuide(){if(!$('revenge-guide'))return;$('revenge-guide').textContent=!adminRevenge.unlocked?'Un-code the Admin to earn Line of Code and unlock the revenge encounter.':adminRevenge.defeated?'Revenge Admin defeated · Visit the Admin on the sky island for a Glitched Dragon.':boss?.revenge?'Revenge Admin active · use Destroy, Input and Overrun.':adminRevenge.warning>0?'The Admin is rebuilding… '+Math.ceil(adminRevenge.warning)+'s.':'Revenge Admin · 30% return chance every 45 seconds while exploring above ground. Line of Code is your counter.'}
function revengeSpawnEligible(){return !spawnProtectionActive()&&adminRevenge.unlocked&&!adminRevenge.defeated&&started&&!paused&&!boss&&!adminReckoning&&!skyTrial&&!bossIntro&&p.hp>0&&!(adminUnlocked&&!admin.naturalBosses)&&p.y<surface[Math.max(0,Math.min(W-1,Math.floor(p.x/T)))]*T+80}
function rollAdminRevenge(roll=rand()){if(!revengeSpawnEligible()||time<adminRevenge.next)return false;adminRevenge.next=time+45;if(roll>=.3)return false;adminRevenge.warning=5;resetNaturalEncounter();notify('The Admin is rebuilding himself… Revenge arrives in 5 seconds!');toastTimer=5;return true}
function tickAdminRevenge(dt){if(!revengeSpawnEligible()){updateRevengeGuide();return}if(adminRevenge.warning>0){adminRevenge.warning=Math.max(0,adminRevenge.warning-dt);if(adminRevenge.warning<=0)spawnRevengeAdmin()}else if(time>=adminRevenge.next)rollAdminRevenge();updateRevengeGuide()}
function spawnRevengeAdmin(){if(!adminRevenge.unlocked||adminRevenge.defeated||boss||adminReckoning||bossIntro||!started)return false;adminRevenge.warning=0;adminRevenge.next=time+90;boss={revenge:true,name:'Admin · Revenge Protocol',id:6,kind:7,color:'#d597f4',hp:14000,max:14000,x:2610*T,y:0,w:64*admin.bossSize,h:76*admin.bossSize,vx:0,vy:0,timer:1.4,age:0,hit:0,phase:1,dive:0,diveTimer:2.8,ground:false};sealArena(6);notify('REVENGE PROTOCOL · You deleted my code. I rebuilt it.');return true}
function drawRevengeIntro(){const t=bossIntro.age/bossIntro.duration,x=boss.x+boss.w/2-camera.x,y=boss.y+boss.h/2-camera.y;ctx.save();ctx.fillStyle='#0c0829aa';ctx.fillRect(0,0,vw,58);ctx.fillRect(0,vh-90,vw,90);ctx.strokeStyle='#d1a2f5';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,100*(1-t)+30,0,Math.PI*2);ctx.stroke();ctx.font='10px monospace';ctx.fillStyle='#caa4f4';ctx.textAlign='center';for(let j=0;j<10;j++){const a=j*Math.PI/5+t*3;ctx.fillText(j%2?'restore(npc);':'backup.exe',x+Math.cos(a)*115*(1-t),y+Math.sin(a)*95*(1-t))}ctx.font='bold 21px monospace';ctx.fillStyle='#f3d9ff';ctx.fillText('ADMIN · REVENGE PROTOCOL',vw/2,vh-57);ctx.font='12px monospace';ctx.fillStyle='#c7b8e3';ctx.fillText('“You forgot about the backup.” · Defeat him with Line of Code.',vw/2,vh-30);ctx.restore()}
function updateRevengeAdmin(b,dt,rage){const a=activeArena,center=(a?.center||2610)*T,floor=(a?.floor||surface[2610])*T;b.diveTimer-=dt;if(b.diveTimer<=0){b.dive=.45;b.diveTimer=rage?2.1:3.1;const angle=Math.atan2(p.y-b.y,p.x-b.x);b.vx=Math.cos(angle)*(rage?450:330);b.vy=Math.sin(angle)*(rage?450:330)}if(b.dive>0){b.dive-=dt;b.x+=b.vx*dt;b.y+=b.vy*dt}else{const targetX=p.x+(Math.sin(b.age*1.2)>0?125:-125),targetY=p.y-90+Math.sin(b.age*2)*25;b.x+=(targetX-b.x)*Math.min(1,dt*2);b.y+=(targetY-b.y)*Math.min(1,dt*2)}b.x=Math.max(center-300,Math.min(center+260,b.x));b.y=Math.max((a?.top||5)*T+40,Math.min(floor-b.h,b.y));if(b.timer<=0){fireSpread(b,rage?9:5,rage?260:205,'#e69ad3');for(let j=0;j<(rage?3:1);j++){const angle=Math.atan2(p.y+14-b.y,p.x+6-b.x)+(j-1)*.12;projectile(b.x+b.w/2,b.y+b.h/2,Math.cos(angle)*310,Math.sin(angle)*310,true,'#dca9ff',22);Object.assign(shots.at(-1),{codeShot:true,tool:j,life:2.5,w:13,h:11})}b.timer=rage?.85:1.35}}
function drawRevengeAdmin(c,b){const x=b.w/(admin.bossSize||1)/2,y=65;c.save();c.translate(x,y);c.scale(1.45,1.45);drawSkyAdminAvatar(0,0,p.x<b.x?-1:1);drawNpcOniFists(0,0,time*1.5);c.fillStyle=b.hit>0?'#ffffff':'#ef81cb';c.fillRect(-10,-34,20,4);c.fillRect(-7,-22,14,3);c.fillStyle='#271631';c.fillRect(-5,-21,3,1);c.fillRect(2,-21,3,1);c.restore();c.save();c.font='9px monospace';c.textAlign='center';c.fillStyle='#e6a4f8';c.fillText('revenge.protocol()',x,-14);for(let j=0;j<5;j++){c.fillStyle=j%2?'#dd81e5':'#a2d8ed';c.fillRect(x+Math.cos(time*2+j)*42,30+Math.sin(time*2+j)*31,3,3)}c.restore()}
function finishRevengeAdmin(){adminRevenge.defeated=true;skyAdmin.vanished=false;adminRevenge.warning=0;boss=null;releaseArena();for(const shot of shots)if(shot.enemy)shot.life=0;p.hp=100;bag[5]+=25;updateRevengeGuide();inventory();updateAdventure();notify('Revenge defeated · +25 crystals. Visit the sky Admin for your Glitched Dragon!');beep(780)}


