 rootHusk:{zone:0,name:'Rootbound Husk',morph:true,body:'tree',w:23,h:25,hp:85,speed:85,damage:13,color:'#a2bb71',dark:'#65513e',detail:'A quiet sapling that unfolds into a charging wooden beast.'},
 tideRay:{zone:1,name:'Tide Ray',fly:true,body:'ray',w:36,h:18,hp:65,speed:120,damage:12,color:'#85d7df',dark:'#3c6a89',detail:'A gliding manta that dives in smooth arcs above the coast.'},
 reefMimic:{zone:1,name:'Reef Mimic',morph:true,body:'crab',w:28,h:17,hp:110,speed:95,damage:15,color:'#d5b4a1',dark:'#805f71',detail:'A harmless-looking shell opens into a snapping reef crab.'},
 cinderBat:{zone:2,name:'Cinder Bat',fly:true,shot:true,body:'bat',w:30,h:19,hp:80,speed:135,damage:14,color:'#f2a075',dark:'#784354',detail:'A flame-winged bat that circles and spits embers.'},
