 frostOwl:{zone:3,name:'Frost Owl',fly:true,shot:true,body:'bird',w:32,h:23,hp:95,speed:110,damage:14,color:'#d9f3fb',dark:'#678bad',detail:'A broad-winged owl firing ice shards between swoops.'},
 iceGolem:{zone:3,name:'Icebound Golem',morph:true,body:'golem',w:27,h:22,hp:180,speed:80,damage:18,color:'#b9e5f3',dark:'#567c9f',detail:'An icy boulder rises into a heavy golem before charging.'},
 duneScarab:{zone:4,name:'Dune Scarab',phase:true,body:'scarab',w:27,h:18,hp:115,speed:135,damage:17,color:'#e3c178',dark:'#90683f',detail:'Burrows out of sight for 2.2 seconds, leaving a dust trace.'},
