const spawnProtection={remaining:0};
function spawnProtectionActive(){return started&&spawnProtection.remaining>0&&!adminUnlocked&&!admin.god}
function updateSpawnProtectionHud(){const active=spawnProtectionActive();$('spawn-protection').classList[active?'remove':'add']('hidden');const label=active?'SPAWN SHIELD · '+Math.ceil(spawnProtection.remaining)+'s':'';if($('spawn-protection').textContent!==label)$('spawn-protection').textContent=label}
function cancelSpawnProtection(){if(spawnProtection.remaining>0)bossSafetyUntil=Math.min(bossSafetyUntil,time);spawnProtection.remaining=0;updateSpawnProtectionHud()}
function grantSpawnProtection(){if(adminUnlocked||admin.god){spawnProtection.remaining=0;bossSafetyUntil=time}else{spawnProtection.remaining=60;bossSafetyUntil=Math.max(bossSafetyUntil,time+60)}updateSpawnProtectionHud()}
function tickSpawnProtection(dt){if(adminUnlocked||admin.god){if(spawnProtection.remaining>0)cancelSpawnProtection();return}spawnProtection.remaining=Math.max(0,spawnProtection.remaining-dt);updateSpawnProtectionHud()}


function initializeGlitchedDragon(){mounts.push({name:'Glitched Dragon',speed:390,jump:500,fly:true,color:'#c38aff',detail:'Flying glitch dragon · Admin panel, or claim from the sky Admin after defeating Revenge Protocol.'});trust.push(0)}
function updateSkyDragonDialogue(){const peace=adminRevenge.defeated;$('sky-dragon').classList[peace?'remove':'add']('hidden');$('sky-dragon').textContent=tamed.has(3)?'Summon Glitched Dragon':'Claim & ride Glitched Dragon';$('sky-npc-dialogue').textContent=peace?'You defeated my revenge protocol. I admit it: you are the creator. Take the Glitched Dragon as our pact.':'Oh, you found my island! I look familiar, don’t I? These weapons slipped through the cracks in the world. Take one and see what happens.';$('sky-trial-info').textContent=peace?'Your dragon can fly. Hold W / Space to rise and S to descend; use the Ride button to dismount. Weapon rolls are gifts now—no more trials.':'Each roll begins a 60-second weapon trial. Close this window and try your weapon anywhere. When time runs out, the Admin appears for an unstoppable finale. If you have Oni fists or Admin access, answer “I’m you” to claim the arsenal. Further rolls do not reset the timer.'}
function summonGlitchedDragon(source){if(!started||p.hp<=0||adminReckoning||bossIntro)return false;const allowed=source==='admin'?adminUnlocked:source==='npc'&&adminRevenge.defeated&&nearSkyAdmin()&&!$('sky-npc-panel').classList.contains('hidden');if(!allowed){notify(source==='npc'?'Defeat the revenge Admin, then speak to him on the sky island.':'Unlock the Admin panel to summon this mount.');return false}tamed.add(3);trust[3]=3;mountChoice=3;mount=3;if(codeInputFlightActive())codeWeapon.inputFlight=false;p.vx=p.vy=0;burst(p.x+p.w/2,p.y+p.h,'#d4a1ff',24);closePanels();updateAdventure();notify('Glitched Dragon summoned · W / Space to fly · S to descend · Ride to dismount');return true}
function drawGlitchedDragon(c,clock,speed,airborne){const flap=Math.sin(clock*(airborne?7:3)),step=creatureStep(speed,clock),outline='#211b3d',dark='#45336b',body='#8270be',light='#bba5ee',cyan='#8df1e8',pink='#e893f1';
 // Membranes have ribs and torn edges, with clear space above the rider's saddle.
 for(let wing=0;wing<2;wing++){c.save();c.translate(wing?-7:-16,wing?-15:-18);c.rotate((wing?.03:-.18)+flap*(airborne?.15:.04));c.globalAlpha=wing?1:.6;pixelPolygon(c,[[0,0],[-14,-31],[-35,-51+flap*7],[-53,-31],[-42,-23],[-44,-8],[-23,-10],[-18,2]],outline);pixelPolygon(c,[[-4,-3],[-16,-27],[-35,-46+flap*7],[-48,-31],[-37,-22],[-39,-12],[-23,-15],[-18,-3]],wing?'#675294':'#3d4977');pixelLine(c,0,0,-35,-49+flap*7,cyan,2);pixelLine(c,-15,-27,-49,-31,pink,1);pixelLine(c,-15,-27,-39,-11,light,1);pixelLine(c,-15,-27,-20,-2,light,1);c.fillStyle=pink;c.fillRect(-32,-28,8,2);c.fillStyle=cyan;c.fillRect(-38,-38,4,3);c.restore()}
 let old=[-27,-13];for(let j=1;j<=9;j++){const next=[-27-j*5,-13+Math.sin(clock*3+j*.5)*(3+j*.4)+j*.6];pixelLine(c,old[0],old[1],next[0],next[1],outline,Math.max(2,9-j*.65));pixelLine(c,old[0],old[1]-1,next[0],next[1]-1,j%2?body:light,Math.max(1,5-j*.4));old=next}pixelPolygon(c,[[old[0]+3,old[1]],[old[0]-7,old[1]-5],[old[0]-4,old[1]+5]],pink);
 for(let leg=0;leg<3;leg++){const hip=-19+leg*16,foot=hip+(airborne?-5:(leg%2?step:-step));pixelLine(c,hip,-12,hip-2,-6,dark,5);pixelLine(c,hip-2,-6,foot,airborne?-6:-1,body,4);c.fillStyle=light;c.fillRect(foot-3,airborne?-7:-2,9,2);c.fillStyle=cyan;c.fillRect(foot+3,airborne?-7:-2,2,2)}
 // Glowing offset profiles act as RGB ghost images without flickering the body away.
 const profile=[[-31,-13],[-22,-22],[-5,-21],[12,-18],[20,-29],[33,-34],[45,-29],[50,-22],[39,-19],[29,-18],[23,-8],[4,-4],[-19,-5]];
 c.save();c.globalAlpha=.28;for(const [offset,color]of [[-3,cyan],[3,pink]]){c.strokeStyle=color;c.lineWidth=2;c.beginPath();profile.forEach(([x,y],i)=>i?c.lineTo(x+offset,y):c.moveTo(x+offset,y));c.closePath();c.stroke()}c.restore();pixelPolygon(c,profile,outline);pixelPolygon(c,[[-28,-12],[-20,-19],[-4,-18],[13,-15],[22,-27],[33,-31],[44,-27],[46,-23],[37,-22],[27,-20],[21,-10],[3,-7],[-18,-8]],body);pixelPolygon(c,[[-25,-10],[-7,-10],[8,-10],[22,-16],[18,-9],[1,-5],[-17,-7]],light);pixelPolygon(c,[[24,-29],[23,-43],[30,-33]],dark);pixelPolygon(c,[[34,-31],[40,-42],[39,-31]],light);c.fillStyle=cyan;c.fillRect(35,-28,6,3);c.fillStyle='#fcf4e3';c.fillRect(40,-27,2,1);c.fillStyle=outline;c.fillRect(43,-24,4,1);c.fillStyle='#eee7ed';c.fillRect(40,-21,2,3);c.fillRect(45,-22,2,3);
 for(let j=0;j<7;j++){const x=-21+j*6;c.fillStyle=j%2?cyan:pink;c.fillRect(x,-20+Math.sin(j)*2,3,4);c.fillStyle=dark;c.fillRect(x+1,-13,3,2)}
 for(let j=0;j<14;j++){const a=clock*(.6+j%3*.13)+j*2.4,x=Math.round(-8+Math.cos(a)*(28+j*2.6)),y=Math.round(-25+Math.sin(a)*(18+j));c.save();c.globalAlpha=.25+(j%3)*.16;if(j%4===0){c.font='8px monospace';c.fillStyle=j%2?cyan:pink;c.fillText(j%3?'404':'</>',x,y)}else{checker(c,x,y,3+j%3,3,2)}c.restore()}
 const tear=Math.floor(clock*6)%9;if(tear<3){c.save();c.globalAlpha=.65;c.fillStyle=tear%2?cyan:pink;c.fillRect(-23+tear*8,-15-tear*2,24,2);c.fillStyle='#1e1233';c.fillRect(14,-25,11,2);c.restore()}
}

