if(document.modelContext?.registerTool){const life=new AbortController();for(const tool of [{name:'read_adventure_state',description:'Read current health, inventory, location, tools and objective.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({health:p.hp,inventory:{...bag},pickaxe:['','wood','copper','crystal / iron','gold','cinder'][pick],mount:mount<0?'On foot':mounts[mount].name,boss:boss?{name:boss.name,health:boss.hp}:null,bossesDefeated:[...defeated],naturalBosses:{status:naturalBossStatus(biomeAt()),pending:naturalEncounter.pending>=0?bossDefs[naturalEncounter.pending].name:null},dashReady:dashCooldown<=0,position:{x:Math.floor(p.x/T),y:Math.floor(p.y/T)},oxygen:Math.ceil(oxygen),buffs:{...buffs},nearbyStations:Object.keys(stationDefs).filter(nearbyStation),recipeCount:recipes.length,hunger:Math.ceil(hunger),weapon:items[weapon].name,armor:armor?items[armor].name:null,gear:[...accessories],tamedMounts:[...tamed].map(i=>mounts[i].name),biome:biomes[biomeAt()].name,pet:activePet?petDefs[activePet.id].name:null,adminUnlocked,objective:$('quest').textContent,started,paused})},{name:'craft_item',description:'Craft a recipe using collected resources, as in the Crafting panel.',inputSchema:{type:'object',properties:{recipe:{type:'string',enum:recipes.map(r=>r.name)}},required:['recipe'],additionalProperties:false},execute:input=>{const i=recipes.findIndex(r=>r.name===input.recipe);if(i<0)throw new Error('Unknown recipe');if(!started)throw new Error('Enter the wilds first');if(!craft(i))throw new Error('Not enough resources, item already owned, or health is full');return {crafted:recipes[i].name,inventory:{...bag}}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
